package DBFetchLogs;
use strict;
use warnings;
use parent 'DBBase';
use Time::Piece;

our @VALID_COLUMNS = qw(
    id batch_id epoch outcome total week_number month year
    day_of_the_week hour log_category usage_category rtoken
    domain segment foreign_id
);

sub new {
    my ($class, $db_path) = @_;
    my $self = $class->SUPER::new($db_path);
    $self->{valid_columns} = \@VALID_COLUMNS;
    $self->{table_name} = 'fetch_logs';
    $self->create_table;
    return $self;
}

sub create_table {
    my $self = shift;
    my $exists = $self->{db}->db->query("SELECT name FROM sqlite_master WHERE type='table' AND name='fetch_logs'")->array;

    unless ($exists) {
        $self->{db}->db->query(q{
            CREATE TABLE fetch_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                epoch INTEGER,
                outcome INTEGER DEFAULT -1,
                total INTEGER DEFAULT -1,
                week_number INTEGER DEFAULT -1,
                month INTEGER DEFAULT -1,
                year INTEGER DEFAULT -1,
                day_of_the_week INTEGER DEFAULT -1,
                hour INTEGER DEFAULT -1,
                foreign_id TEXT,
                batch_id TEXT,
                log_category TEXT,
                usage_category TEXT,
                rtoken TEXT,
                domain TEXT,
                segment TEXT
            )
        });
        $self->create_indexes;
    }
}

sub create_indexes {
    my $self = shift;
    $self->{db}->db->query('CREATE INDEX fetch_logs_epoch ON fetch_logs(epoch)');
    $self->{db}->db->query('CREATE INDEX fetch_logs_rtoken ON fetch_logs(rtoken)');
    $self->{db}->db->query('CREATE INDEX fetch_logs_category ON fetch_logs(log_category)');
    $self->{db}->db->query('CREATE INDEX fetch_logs_year ON fetch_logs(year)');
    $self->{db}->db->query('CREATE INDEX fetch_logs_month ON fetch_logs(month)');
    $self->{db}->db->query('CREATE INDEX fetch_logs_week_number ON fetch_logs(week_number)');
    $self->{db}->db->query('CREATE INDEX fetch_logs_day_of_the_week ON fetch_logs(day_of_the_week)');
    $self->{db}->db->query('CREATE INDEX fetch_logs_hour ON fetch_logs(hour)');
}

sub create_log {
    my ($self, $params) = @_;

    # Ensure required fields are present
    my @required = qw(log_category usage_category batch_id outcome rtoken segment);
    my $time = localtime;
    $params->{epoch} = $time->epoch;
    $params->{week_number} = $time->week;
    $params->{month} = $time->mon;
    $params->{year} = $time->year;
    $params->{day_of_the_week} = $time->wday;
    $params->{hour} = $time->hour;

    for my $field (@required) {
        unless (exists $params->{$field}) {
            warn "Missing required field: $field";
            return 0;
        }
    }

    return $self->insert_one($params);
}

sub get_logs_by_timeframe {
    my ($self, $params) = @_;
    my $where_clause = "";
    my @values;

    if ($params->{year}) {
        $where_clause .= "year = ?";
        push @values, $params->{year};

        if ($params->{month}) {
            $where_clause .= " AND month = ?";
            push @values, $params->{month};
        }

        if ($params->{week_number}) {
            $where_clause .= " AND week_number = ?";
            push @values, $params->{week_number};
        }
    }

    return [] unless $where_clause;

    return $self->{db}->db->query(
        "SELECT * FROM fetch_logs WHERE $where_clause ORDER BY epoch DESC",
        @values
    )->hashes->to_array;
}

sub get_stats_by_timeframe_sth {
    my ($self, $params) = @_;
    my $group_by = $params->{group_by} || 'day_of_the_week';
    my @where_arr = ();
    my $where_clause = "";
    my @values;

    if ($params->{year}) {
        push @where_arr, "year = ?";
        push @values, $params->{year};

        if ($params->{month}) {
            push @where_arr, "month = ?";
            push @values, $params->{month};
        }

        if ($params->{week_number}) {
            push @where_arr, "week_number = ?";
            push @values, $params->{week_number};
        }
    }

    if ($params->{rtoken}) {
        push @where_arr, "rtoken = ?";
        push @values, $params->{rtoken};
    }

    if ($params->{log_category}) {
        push @where_arr, "log_category = ?";
        push @values, $params->{log_category};
    }

    if ($params->{usage_category}) {
        push @where_arr, "usage_category = ?";
        push @values, $params->{usage_category};
    }

    if (exists $params->{elapsed_time} && defined $params->{elapsed_time}) {
        my $timestamp = time() - $params->{elapsed_time};
        push @where_arr, "epoch > ?";
        push @values, $timestamp;
    }

    if (@where_arr) {
        $where_clause = "WHERE " . join(" AND ", @where_arr);
    }

    my @order_arr = ();
    foreach my $order_key (qw(rtoken day_of_the_week hour)) {
        if ($group_by =~ qr/\Q$order_key\E/i) {
            push @order_arr, "$order_key ASC";
        }
    }
    my $order_clause = @order_arr ? "ORDER BY " . join(", ", @order_arr) : "";

    return $self->{db}->db->query(qq{
        SELECT $group_by, SUM(outcome) as outcome, COUNT(*) as total
        FROM fetch_logs
        $where_clause
        GROUP BY $group_by
        $order_clause
    }, @values);
}

sub get_logs_sth {
    my ($self, $params) = @_;
    my @where;
    my @values;

    foreach my $column (@{$self->{valid_columns}}) {
        if (exists $params->{$column} && defined $params->{$column}) {
            push @where, "$column = ?";
            push @values, $params->{$column};
        }
    }

    # Add elapsed time filter if provided
    if (exists $params->{elapsed_time} && defined $params->{elapsed_time}) {
        my $timestamp = time() - $params->{elapsed_time};
        push @where, "epoch > ?";
        push @values, $timestamp;
    }

    my $where_clause = @where ? "WHERE " . join(" AND ", @where) : "";

    return $self->{db}->db->query(
        "SELECT * FROM fetch_logs
        $where_clause
        ORDER BY id ASC",
        @values
    );
}

