#pragma once
#include <RLGymCPP/Rewards/Reward.h>

namespace RLGC {

class GoalSpeedReward : public Reward {
public:
    GoalSpeedReward() {}

    virtual float GetReward(const Player& player, const GameState& state, bool isFinal) override {
        if (!state.goalScored) {
            return 0.0f;
        }
        bool scored = (player.team != RS_TEAM_FROM_Y(state.ball.pos.y));
        float ballSpeed = state.ball.vel.Length();
        float normalizedBallSpeed = ballSpeed / CommonValues::BALL_MAX_SPEED;
        float ScaledNormalizedBallSpeed = std::max(0.0f, std::min(1.0f, normalizedBallSpeed));
        if (scored) {
            return ScaledNormalizedBallSpeed;
        } else {
            return -ScaledNormalizedBallSpeed;
        }
    }
};

// https://github.com/AechPro/rocket-league-gym-sim/blob/main/rlgym_sim/utils/reward_functions/common_rewards/ball_goal_rewards.py
class FVelocityBallToGoalReward : public Reward {
public:
	bool ownGoal = false;
	FVelocityBallToGoalReward(bool ownGoal = false) : ownGoal(ownGoal) {}

	virtual float GetReward(const Player& player, const GameState& state, bool isFinal) {
		bool targetOrangeGoal = player.team == Team::BLUE;
		if (ownGoal)
			targetOrangeGoal = !targetOrangeGoal;

		Vec targetPos = targetOrangeGoal ? CommonValues::ORANGE_GOAL_CENTER : CommonValues::BLUE_GOAL_CENTER;

