class BetterKickoffReward : public Reward {
public:
    BetterKickoffReward() {}

    virtual float GetReward(const Player& player, const GameState& state, bool isFinal) override {
        float playerDist = std::numeric_limits<float>::max();
        float opponentDist = std::numeric_limits<float>::max();
        if (state.ball.vel.IsZero() && state.ball.pos.IsZero()) {
            const Player* opponent = nullptr;
            for (const auto& p : state.players) {
                if (p.carId != player.carId) {
                    opponent = &p;
                    break;
                }
            }

            if (opponent) {
                float playerDist = player.pos.Length2D();
                float opponentDist = opponent->pos.Length2D();
            }
            if (playerDist < opponentDist) {
                return 1.0f;
            } else {
                return -1.0f;
            }
        }
        return 0.0f;
    }
};

class BetterSaveReward : public Reward {
public:
    BetterSaveReward() {}

    virtual float GetReward(const Player& player, const GameState& state, bool isFinal) override {
        if (!player.eventState.save) {
            return 0.0f;
        }

        // check if the save is making the ball not going in the goal
        bool targetOrangeGoal = player.team == Team::BLUE;
        Vec targetPos = targetOrangeGoal ? CommonValues::ORANGE_GOAL_CENTER : CommonValues::BLUE_GOAL_CENTER;
        Vec ballDirToGoal = (targetPos - state.ball.pos).Normalized();
        float ballDirGoal = ballDirToGoal.Dot(state.ball.vel / CommonValues::BALL_MAX_SPEED);
        if (state.prev->ball.vel.Length() > 1000.f && ballDirGoal <= 0.0f) {
            float distanceToGoal = (targetPos - state.ball.pos).Length() / RLConst::ARENA_EXTENT_Y;
            float BaseReward = state.prev->ball.vel.Length() / 3400.f;
            float FinalReward = BaseReward * (1.f - distanceToGoal);
        }

        return 0.0f;
    }
};

class BoostCollection : public Reward {
public:
    BoostCollection() {}

    virtual float GetReward(const Player& player, const GameState& state, bool isFinal) override {
        float reward = 0.0f;
        if (player.boost > player.prev->boost) {
            float boost_calc = (1 - std::sqrt(player.prev->boost)) * 0.7f + 0.3f;
            reward += boost_calc;
        }
        return reward;
    }
};

class AerialDistanceReward : public Reward {
public:
	int RampHeight = 256;
    std::map<int, bool> got_rst;
	float heightScale;
	float distanceScale;
	float carDistance;
    float rollScale;
    float rollDistance;
	float ballDistance;
    float rollAccumulation;
	int currentCarId = 0;
    AerialDistanceReward(float heightScale, float distanceScale, float rollScale) {
	    this->heightScale = heightScale;
	    this->distanceScale = distanceScale;
        this->rollScale = rollScale;
	};
	const Player* findCarOnField(const GameState& state, int carID) {
		for (auto& player : state.players)
			if (player.carId == carID)
				return &player;
		return NULL;
	};
    float cosineSimilarity(Vec a, Vec b) {
        return (a.Length() == 0 || b.Length() == 0) ? 0 : a.Dot(b) / (a.Length() * b.Length());
    }
    virtual void Reset(const GameState& state) {
		int currentCarId = 0;
        got_rst.clear();
	};

    virtual float GetReward(const Player& player, const GameState& state, bool isFinal) override {
        float reward = 0;
        bool isCurrent = (currentCarId != 0 && currentCarId == player.carId);
        bool got_reset = (!player.isOnGround && !player.hasJumped);
        float down = -(player.rotMat.up.z);

        if (got_reset && down > 0 && got_rst.find(player.carId) == got_rst.end()) {
            got_rst[player.carId] = true;
        }

        if (player.isOnGround && player.pos.z < RampHeight) {
            got_rst[player.carId] = false;
        }

        // Define enemy goal position based on team
        Vec enemy_goal_pos = (player.team == Team::BLUE) ? Vec(0, 5120, 320) : Vec(0, -5120, 320);
        if (player.pos.z < RampHeight) {
			if (isCurrent) {
				isCurrent = false;
				currentCarId = 0;
			}
		}
        else if (player.ballTouchedStep && !isCurrent) {
			isCurrent = true;
			ballDistance = 0;
			carDistance = 0;
            rollDistance = 0;
			reward = heightScale * RS_MAX(player.pos.z + state.ball.pos.z - 2 * RampHeight, 0);
		}
        else if (isCurrent && !player.isOnGround) {
			Player currentCar = *findCarOnField(state, currentCarId);

            // Calculate travel vectors and distances
            Vec ball_travel_vec = state.ball.pos - state.prev->ball.pos;
            Vec car_travel_vec = player.pos - currentCar.pos;
            Vec ball_goal_vec = enemy_goal_pos - state.ball.pos;
            Vec car_goal_vec = enemy_goal_pos - player.pos;

            float ball_dist_align = cosineSimilarity(ball_travel_vec, ball_goal_vec);
            float car_dist_align = cosineSimilarity(car_travel_vec, car_goal_vec);

            ball_dist_align = std::max(0.0f, ball_dist_align);
            car_dist_align = std::max(0.0f, car_dist_align);

            carDistance += player.pos.Dist(currentCar.pos);
            ballDistance += state.ball.pos.Dist(state.prev->ball.pos);
            float rollAction = player.prevAction.roll;
            if (rollAction == 1.0f) { // allow only one direction roll which is 1.0f
                rollAccumulation = rollDistance + player.prevAction.roll;
            } else {
                rollAccumulation = 0;
            }

			if (player.ballTouchedStep) {
                float effectiveDistanceScale = (got_rst[player.carId]) ? distanceScale * 4 : distanceScale;
				reward = effectiveDistanceScale * ((carDistance + ballDistance + rollDistance) * (car_dist_align + ball_dist_align));
				carDistance = 0;
				ballDistance = 0;
                rollDistance = 0;
			};
		};

        if (isCurrent) {
			currentCarId = player.carId;
		};

        return reward / (2 * CommonValues::BACK_WALL_Y);
	    };
    };

