        // Add boost
        energy += 7.97e5f * (player.boost / 100.0f) * 100.0f;

        float norm_energy = energy / max_energy;
        if (player.isDemoed) {
            norm_energy = 0.0f;
        }

        return norm_energy;
    }
};

