                if (temp.node.right != null) {
                    queue.add(new Info2(temp.node.right, temp.hd + 1));
                    max = Math.max(max, temp.hd + 1);   // to see if we are going further right.
                }
            }
        }

        for (int i = min; i <= max; i++) {
            System.out.print(map.get(i).data + " ");
        }
        System.out.println();
    }

