# T1
# write function to get factorial of a number
def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)


# T2
# write function to get fibonatchi of a number
def fibonacci(n):
    if n <= 1:
        return n
    else:
        return fibonacci(n-1) + fibonacci(n-2)


# T3
# write function to get caeser cipher of a string
def caeser_cipher(text, shift):
    result = ""
    for char in text:
        if char.isalpha():
            shift_amount = shift % 26
            if char.islower():
                new_char = chr(((ord(char) - ord('a') + shift_amount) % 26) + ord('a'))
            else:
                new_char = chr(((ord(char) - ord('A') + shift_amount) % 26) + ord('A'))
            result += new_char
        else:
            result += char
    return result

