import { program } from 'commander';
import { version } from '../../package.json';
import * as babel from '@babel/core';
import { glob } from 'glob';
import path from 'path';
import fs from 'fs';
import { makePkg, postEsm } from './postbuild';

export async function run() {
  program.name('dev-dep-scripts').version(version);
  program
    .command('build-mf-package')
    .requiredOption('-d, --destination <destination>', 'дирректория файлов билда', 'package')
    .requiredOption('-s, --source <source>', 'файлы исходников, например src/**/*.{js,jsx,ts,tsx}')
    .description('Собирает пакет для mf-сервиса')
    .action(async options => {
      const { babelConfig: cjsConfig } = await import('./babel/babel.config.cjs.js');
      const { babelConfig: esmConfig } = await import('./babel/babel.config.esm.js');
      const cjsDir = path.join(options.destination, 'cjs');
      const esmDir = path.join(options.destination, 'esm');
      const ignored = ['**/__test__/**/*', '**/__mocks__/**/*', '**/*.d.ts'];
      const filenames = glob.sync(options.source, {
        // ignore: ['**/__test__/**/*', '**/__mocks__/**/*', '**/*.d.ts'],
        dotRelative: true,
      });

      for (const filename of filenames) {
        await transpile(filename, path.join(options.destination, 'cjs'), {
          ...cjsConfig,
          ignore: [...(cjsConfig?.ignore || []), ...ignored],
        });
        await transpile(filename, path.join(options.destination, 'esm'), {
          ...esmConfig,
          ignore: [...(esmConfig?.ignore || []), ...ignored],
        });
      }

      await makePkg('cjs', cjsDir);
      await makePkg('esm', esmDir);

      await postEsm(esmDir);
    });
  program.parse();
}

async function transpile(
  source: string,
  destination: string,
  babelConfig: babel.TransformOptions,
  fileDir?: string,
) {
  const stat = fs.statSync(source);
  if (stat.isDirectory()) {
    fs.readdirSync(source, { recursive: true, withFileTypes: true })
      .filter(fileData => {
        // exclude directory entries from readdir results
        if (fileData.isDirectory()) return false;
        return fileData.name[0] !== '.';
      })
      .map(dirent => path.join(dirent.path, dirent.name))
      .forEach(filepath => {
        transpile(filepath, destination, babelConfig, source);
      });
  } else {
    const relative = path.relative(fileDir ? fileDir : path.dirname(source), source);
    const initialDest = path.join(destination, relative);
    if (!ALLOWED_EXTS.includes(path.extname(source))) {
      copyFileSync(source, initialDest);
      return;
    }
    const result = await babel.transformFileAsync(source, {
      ...babelConfig,
      sourceFileName: path.relative(`${initialDest}/..`, source),
    });
    if (result && result.code) {
      const compiledDest = path.join(
        path.dirname(initialDest),
        `${path.basename(initialDest, path.extname(initialDest))}.js`,
      );
      if (result.map) {
        const mapDest = `${compiledDest}.map`;
        result.code = addSourceMappingUrl(result.code, mapDest);
        result.map.file = path.basename(relative);
        outputFileSync(mapDest, JSON.stringify(result.map));
      }
      outputFileSync(compiledDest, result.code);
    } else {
      copyFileSync(source, initialDest);
    }
  }
}

const ALLOWED_EXTS = ['.js', '.ts', '.tsx', '.jsx', '.mjs'];

function addSourceMappingUrl(code: string, loc: string): string {
  return `${code}
//# sourceMappingURL=${path.basename(loc)}`;
}

