function copyFileSync(source: string, destination: string) {
  outputFileSync(destination, fs.readFileSync(source));
  try {
    fs.chmodSync(destination, fs.statSync(source).mode);
  } catch (_) {
    console.warn(`Cannot change permissions of ${destination}`);
  }
}

function outputFileSync(filePath: string, data: string | Buffer): void {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, data);
}

