    display_description network search_id2
);

sub new {
    my ($class, $db_path) = @_;
    my $self = $class->SUPER::new($db_path);
    $self->{valid_columns} = \@VALID_COLUMNS;
    $self->{table_name} = 'torrents';
    $self->create_table;
    return $self;
}

sub create_table {
    my $self = shift;
    my $exists = $self->{db}->db->query("SELECT name FROM sqlite_master WHERE type='table' AND name='torrents'")->array;

    unless ($exists) {
        $self->{db}->db->query(q{
            CREATE TABLE torrents (
                id TEXT PRIMARY KEY,
                description TEXT,
                episode TEXT,
                size TEXT,
                episode_number TEXT,
                show_name TEXT,
                link TEXT,
                date TEXT,
                magnet TEXT,
                group_name TEXT,
                group_link TEXT,
                rtoken TEXT,
                assigned_show_name TEXT,
                date_added INTEGER,
                assigned_timestamp INTEGER,
                season TEXT,
                season_number TEXT
            )
        });
        $self->create_indexes;
    }
}

sub create_indexes {
    my $self = shift;
