            AND b.value IN (t.assigned_show_name, t.id, t.episode, t.group_name, t.season))
        AND NOT EXISTS (SELECT 1 FROM blockers b
            WHERE b.blocker_name = 'words' AND t.assigned_show_name LIKE '%' || b.value || '%')
        AND NOT EXISTS (SELECT 1 FROM blockers b
            WHERE b.blocker_name = 'words' AND t.regular_name LIKE '%' || b.value || '%')
    };
    return $self->{db}->db->query($sql)->hashes->to_array;
}

sub with_show_name_sth {
    my ($self, $show_name) = @_;
    return $self->{db}->db->query(q{
        SELECT t.*,
            EXISTS (
                SELECT 1 FROM queued_torrents q 
                WHERE q.torrent_id = t.id
            ) as downloaded,
            CASE 
                WHEN t.season != '' AND EXISTS (
                    SELECT 1 FROM queued_torrents q 
                    WHERE q.category = 'season' AND q.processed = t.season
                ) THEN 1
                WHEN t.episode != '' AND EXISTS (
                    SELECT 1 FROM queued_torrents q 
                    WHERE q.category = 'episode' AND q.processed = t.episode
                ) THEN 1
                ELSE 0 
            END as marked
        FROM torrents t
        WHERE t.assigned_show_name = ?
        ORDER BY season_number ASC, 
            episode_number ASC, 
            CASE WHEN vencode IS NULL OR vencode = '' THEN 1 ELSE 0 END ASC,
            vencode ASC, 
            resolution DESC, 
            CAST(size AS INTEGER) ASC
    }, $show_name);
}

sub clear_all {
    my ($self) = @_;
    return $self->{db}->db->query('DELETE FROM torrents');
}

sub insert_one {
    my ($self, $params) = @_;

    return 0 if $self->with_id($params->{id});

    my $filtered_params = $self->filter_params($params);
    $filtered_params->{date_added} = time() if !defined $filtered_params->{date_added};

    $self->{db}->db->insert($self->{table_name}, $filtered_params);
    return 1;
}

# todo find out how to convert today and yesterday to epoch
sub dates_sth {
    my ($self) = @_;
    return $self->{db}->db->query(q{
        SELECT DISTINCT t1.date_added, t2.id, t2.description, t2.date, t2.date_added, t2.assigned_timestamp
        FROM torrents t1
        JOIN torrents t2 ON t1.date_added = t2.date_added
        WHERE t1.date_added > 1729382400
            AND (t1.assigned_timestamp IS NULL OR t1.assigned_timestamp = '')
        ORDER BY t1.date_added ASC, t2.id ASC
    });
}

sub purge_blockers {
    my ($self) = @_;

    # blocked shows
    $self->{db}->db->query(q{
        WITH blocked_shows AS (
            SELECT value 
            FROM blockers 
            WHERE blocker_name = 'show_name'
        ),
        queued_show_names AS (
            SELECT DISTINCT show_name 
            FROM queued_torrents 
            WHERE show_name IS NOT NULL AND show_name != ''
        ),
        queued_torrent_ids AS (
            SELECT DISTINCT torrent_id 
            FROM queued_torrents
            WHERE torrent_id IS NOT NULL AND torrent_id != ''
        )
        DELETE FROM torrents
        WHERE (
            show_name IN (SELECT value FROM blocked_shows)
            OR assigned_show_name IN (SELECT value FROM blocked_shows)
        )
        AND show_name NOT IN (SELECT show_name FROM queued_show_names)
        AND assigned_show_name NOT IN (SELECT show_name FROM queued_show_names)
        AND id NOT IN (SELECT torrent_id FROM queued_torrent_ids);
    });

    # blocked group_names
    $self->{db}->db->query(q{
        DELETE FROM torrents
        WHERE group_name COLLATE NOCASE IN (
            SELECT value
            FROM blockers 
            WHERE blocker_name = 'group_name'
        )
        AND id NOT IN (
            SELECT torrent_id 
            FROM queued_torrents
            WHERE torrent_id IS NOT NULL OR torrent_id != ''
        );
    });

    # blocked words
    $self->{db}->db->query(q{
        DELETE FROM torrents
        WHERE EXISTS (
            SELECT 1 FROM blockers b 
            WHERE b.blocker_name = 'words'
            AND (
                INSTR(' ' || show_name || ' ', ' ' || b.value || ' ') > 0
                OR INSTR(' ' || assigned_show_name || ' ', ' ' || b.value || ' ') > 0
                OR INSTR(' ' || regular_name || ' ', ' ' || b.value || ' ') > 0
            )
        )
        AND id NOT IN (
            SELECT torrent_id 
            FROM queued_torrents
            WHERE torrent_id IS NOT NULL AND torrent_id != ''
        );
    });
}

sub update_empty_gencoders {
    my ($self) = @_;
    my $sth = $self->{db}->db->query(q{
        SELECT * FROM torrents
        WHERE (gencoder IS NULL OR gencoder = '')
    });
    while (my $torrent = $sth->hash) {
        # must double check gencoder requirements
        my $g = Parsley::GEncoder::parse($torrent->{regular_name}) || Parsley::GEncoder::parse($torrent->{link});
        next if !$g;
        $self->{db}->db->query(q{
            UPDATE torrents SET gencoder = ?
            WHERE id = ?;
        }, $g, $torrent->{id});
    }
}

sub update_empty_vencode {
    my ($self) = @_;
    my $sth = $self->{db}->db->query(q{
        SELECT * FROM torrents
        WHERE (vencode IS NULL OR vencode = '')
    });
    while (my $torrent = $sth->hash) {
        my $v = Hebshti::get_vencode($torrent->{regular_name});
        $self->{db}->db->query(q{
            UPDATE torrents SET vencode = ?
            WHERE id = ?;
        }, $v, $torrent->{id});
    }
}

sub update_gencoder {
    my ($self, $gencoder) = @_;
    my $sth = $self->{db}->db->query(q{
        SELECT * FROM torrents
        WHERE (gencoder IS NULL OR gencoder = '')
        AND regular_name LIKE '%' || ? || '%';
    }, $gencoder);
    my $dblists = DBLists->new($ENV{DB_PATH});
    $dblists->update_cache();
    while (my $torrent = $sth->hash) {
        # must double check gencoder requirements
        my $g = Parsley::GEncoder::parse($torrent->{regular_name}) || Parsley::GEncoder::parse($torrent->{link});
        next if !$g;
        $self->{db}->db->query(q{
            UPDATE torrents SET gencoder = ?
            WHERE id = ?;
        }, $g, $torrent->{id});
    }
}

sub remove_gencoder {
    my ($self, $gencoder) = @_;
    $self->{db}->db->query(q{
        UPDATE torrents SET gencoder = ''
        WHERE gencoder = ?;
    }, $gencoder);
}

