import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import React, { useState, useCallback } from 'react';
import { StructuredResponseSchema, getOllamaSchema } from '../models/ChatModels';
import ollama from 'ollama/browser';
import { systemPrompt } from '../prompts/systemPrompt';
import ReactMarkdown from 'react-markdown';
import '../index.css';

const Chat = () => {
    const [messages, setMessages] = useState([]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [copiedMessageId, setCopiedMessageId] = useState(null);
    const [temperature, setTemperature] = useState(0.7);

    // Extract streaming message update to avoid closure issues
    const updateStreamingMessage = useCallback((content) => {
      setMessages(prev => [
        ...prev.slice(0, -1),
        {
          role: 'assistant',
          content,
          streaming: true
        }
      ]);
    }, []);

    // Extract final message update to avoid closure issues
    const updateFinalMessage = useCallback((content, structuredData) => {
      setMessages(prev => [
        ...prev.slice(0, -1),
        {
          role: 'assistant',
          content, // Keep the original JSON string
          structured: structuredData,
          streaming: false
        }
      ]);
    }, []);

    const handleSubmit = async (e, retryMessageId = null) => {
      e?.preventDefault();

      let userMessageContent;
      let messageHistory;

      if (retryMessageId !== null) {
        // For retry, use the original message
        const originalMessage = messages[retryMessageId - 1];
        if (!originalMessage || originalMessage.role !== 'user') return;

        userMessageContent = 'RETRY: ' + originalMessage.content;
        messageHistory = messages.map(msg => ({
          role: msg.role,
          content: typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content)
        }));

        // Set temperature to 1 for retry
        setTemperature(1.0);
      } else {
        if (!input.trim()) return;
        userMessageContent = input;
        messageHistory = messages.map(msg => ({
          role: msg.role,
          content: typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content)
        }));
      }

      const userMessage = { role: 'user', content: userMessageContent };
      if (!retryMessageId) {
        setInput('');
        setMessages(prev => [...prev, userMessage]);
      }
      setIsLoading(true);

      try {
        // Log the request for debugging
        console.log('Sending request with messages:', [
          { role: 'system', content: systemPrompt },
          ...messageHistory,
          userMessage
        ]);

        const response = await ollama.chat({
          model: 'qwen2.5:32b-32k',
          messages: [
            { role: 'system', content: systemPrompt },
            ...messageHistory,
            userMessage
          ],
          format: getOllamaSchema(),
          options: {
            temperature
          },
          stream: true
        });

        // After sending retry request, remove original response
        if (retryMessageId !== null) {
          setMessages(prev => [...prev.slice(0, retryMessageId), userMessage]);
        }

        // Initialize streaming message
        setMessages(prev => [...prev, {
          role: 'assistant',
          content: '',
          streaming: true
        }]);

        let accumulatedContent = '';

        for await (const part of response) {
          if (part.message?.content) {
            accumulatedContent += part.message.content;
            updateStreamingMessage(accumulatedContent);
          }

          // Check if this is the last chunk
          if (part.done) {
            try {
              const parsedResponse = JSON.parse(accumulatedContent);
              const validatedResponse = StructuredResponseSchema.safeParse(parsedResponse);

              // Log the parsed response for debugging
              console.log('Parsed response:', parsedResponse);

              if (validatedResponse.success) {
                // Log validation success and rating
                console.log('Validation successful, original rating:', validatedResponse.data.response_rating);

                // Log validation success and rating
                console.log('Validation successful, rating:', validatedResponse.data.response_rating);

                // Use the validated response directly since Zod already handles rating bounds
                updateFinalMessage(accumulatedContent, validatedResponse.data);

                // Reset temperature back to 0.7 after retry completion
                if (retryMessageId !== null) {
                  setTemperature(0.7);
                }
              } else {
                console.error('Validation failed:', validatedResponse.error);
                throw new Error('Response validation failed');
              }
            } catch (parseError) {
              console.error('Failed to parse final response:', parseError);
              setMessages(prev => [...prev, {
                role: 'assistant',
                content: 'Sorry, I received an invalid response format.',
                error: true
              }]);
            }
          }
        }
      } catch (error) {
        console.error('Chat error:', error);
        setMessages(prev => [...prev, {
          role: 'assistant',
          content: 'Sorry, I encountered an error processing your request.',
          error: true
        }]);
      } finally {
        setIsLoading(false);
      }
    };

