            if(!vis[i]){
                bfsUtil(graph, i, vis);
            }
        }
    }


    private static void bfsUtil(ArrayList<Edge> graph[], int start, boolean vis[]){
        Queue<Integer> q = new LinkedList<>();
        q.add(start);

        while(!q.isEmpty()){
            int curr = q.remove();

            if(!vis[curr]){
                System.out.print(curr + " ");
                vis[curr] = true; 

                for(int i=0; i<graph[curr].size(); i++){
