    private static void dfsUtil(ArrayList<Edge>[] graph, int curr, boolean vis[]){
        System.out.print(curr + " ");
        vis[curr] = true;

        for(int i=0; i<graph[curr].size(); i++){
            Edge e = graph[curr].get(i);
            if(!vis[e.dest]){
                dfsUtil(graph, e.dest, vis);
            }
        }
    }


    public static boolean hasPath(ArrayList<Edge>[] graph, int src, int des, boolean[] vis){
        if(src == des){
            return true;
        }
        vis[src] = true;
        for(int i=0; i<graph[src].size(); i++){
            Edge e = graph[src].get(i);
            if(!vis[e.dest] && hasPath(graph, e.dest, des, vis)){
                return true;
            }
        }
        return false;
    }

    public static boolean detectCycle(ArrayList<Edge>[] graph){
        boolean vis[] = new boolean[graph.length];
        for(int i=0; i<graph.length; i++){
            if(!vis[i]){
                if(detectCycleUtil(graph, vis, i, -1)){
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean detectCycleUtil(ArrayList<Edge> graph[], boolean[] vis, int curr, int par){
        vis[curr] = true;

        for(int i=0; i<graph[curr].size(); i++){
            Edge e = graph[curr].get(i);
            // case - 3  -> vis[curr] is not true then just repeat it and returns if there is a cycle
            if(!vis[e.dest]){
                if(detectCycleUtil(graph, vis, e.dest, curr)){
                    return true;
                }
            }
            // case - 1 -> vis[curr] is true is and destination is not a parent,then the cycle exists
            else if(e.dest != par){
                return true;
            }
            // case - 3 -> do nothing. -> vis[curr] is not true and destination is not a parent obviously.
        }
        return false;
    }

    public static boolean isBipartite(ArrayList<Edge>[] graph){
        int[] colors = new int[graph.length];
        Arrays.fill(colors, -1); //no color

        for(int i = 0; i < graph.length; i++){
            if(colors[i] == -1){
                if(!isBipartiteUtil(graph, i, colors)){
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isBipartiteUtil(ArrayList<Edge>[] graph, int src, int[] colors){
        Queue<Integer> q = new LinkedList<>();
        q.add(src);
        colors[src] = 0;

        while(!q.isEmpty()){
            int curr = q.remove();
            for(int i=0; i<graph[curr].size(); i++){
                Edge e = graph[curr].get(i);
                if(colors[e.dest] == -1){
                    q.add(e.dest);
                    colors[e.dest] = 1 - colors[curr];
                }
                else if(colors[e.dest] == colors[curr]){
                    return false;
                }
            }
        }
        return true;
    }

    public static boolean isCycle(ArrayList<Edge>[] graph){
        boolean vis[] = new boolean[graph.length];
        boolean stack[] = new boolean[graph.length];
        for(int i=0; i<graph.length; i++){
            if(!vis[i] && isCycleUtil(graph, i, vis, stack)){
                return true;
            }
        }
        return false;
    }

    private static boolean isCycleUtil(ArrayList<Edge>[] graph, int curr, boolean[] vis, boolean[] stack){
        vis[curr] = true;
        stack[curr] = true;

        for(int i=0; i<graph[curr].size(); i++){
            Edge e = graph[curr].get(i);
            if(!vis[e.dest] && isCycleUtil(graph, e.dest, vis, stack)){
                return true;
            }
            else if(stack[e.dest]){
                return true;
            }
        }
        stack[curr] = false;
        return false;
    }

