    if len(iges.bsplines() != 0):
        result["nurbs_curves"] = convert_curves(iges.bsplines)
    return result


def convert_curves(curves: List[pyiges.geometry.RationalBSplineCurve]):
    result = list()
    for curve in curves:
        result.append(convert_curve(curve))
    return result


def convert_curve(curve: pyiges.geometry.RationalBSplineCurve):
    converted = dict()
    converted["type"] = "Nurbs Curve"
    converted["control_points"] = list()
    for p, w in zip(curve.control_points, curve.W):
        list.append({"x": p[0], "y": p[1], "z": p[2], "w": w})
    converted["knots"] = curve.T
    converted["degree"] = curve.M
    return converted

def join(
    data: dict,
    file_data: dict
):
    for key, value in file_data.items():
        if key in data:
            data[key].extend(value)
        else:
            data[key] = value

