import java.util.*;

public class heap {
    static class Heap{
        ArrayList<Integer> arr = new ArrayList<>();
        public void add(int data){
            //add at last idx;
            arr.add(data);

            int x = arr.size() - 1; // x is child index
            int par = (x - 1) / 2; // parent index

            while (arr.get(x) < arr.get(par)) { // min heap  //T.C -> O(log n)
                // swap
                int temp = arr.get(x);
                arr.set(x, arr.get(par)); 
                arr.set(par, temp);

                x = par;
                par = (x - 1) / 2;
            }
        }

        public int peek(){
            return arr.get(0);
        }     

        public int remove(){
            int data = arr.get(0);

            // step 1 - swap first and last
            int lastIdx = arr.size() - 1;
            arr.set(0, arr.get(lastIdx));
            arr.remove(lastIdx);

            // step 2 - fix heap
            int idx = 0;
            while(true){
                int leftIdx = 2 * idx + 1;
                int rightIdx = 2 * idx + 2;
                int minIdx = idx;

                if(leftIdx < arr.size() && arr.get(leftIdx) < arr.get(minIdx)){
                    minIdx = leftIdx;
                }

                if(rightIdx < arr.size() && arr.get(rightIdx) < arr.get(minIdx)){
                    minIdx = rightIdx;
                }
                if(idx == minIdx){
                    break;
                }

                // swap when minIdx value is changed.
                int temp = arr.get(idx);
                arr.set(idx, arr.get(minIdx));
                arr.set(minIdx, temp);

                idx = minIdx;
            }
            return data;
        }
    }

