    public struct function getChartfieldPerformData() {
        var qData = queryExecute(this.chartfieldPerformQuery);
        var projectMap = {};
        var programMap = {};
        for (var i = 1; i <= qData.recordCount; i++) {
            var cf = trim(qData.chartfield[i]);
            var type = qData.ccChartfieldType[i];
            var title = qData.shortTitle[i];
            if (len(cf)) {
                if (type == "p") {
                    projectMap[cf] = { chartfield: cf, projectName: title };
                } else if (listFindNoCase("b,o", type)) {
                    programMap[cf] = { chartfield: cf, programName: title };
                }
            }
        }
        return { projects: projectMap, programs: programMap };
    }

