our @VALID_COLUMNS = qw(
    id description episode size episode_number show_name regular_name
    link date magnet group_name group_link rtoken assigned_show_name date_added
    gencoder vencode resolution assigned_timestamp season season_number
    display_description network search_id2
);

sub new {
    my ($class, $db_path) = @_;
    my $self = $class->SUPER::new($db_path);
    $self->{valid_columns} = \@VALID_COLUMNS;
    $self->{table_name} = 'torrents';
    $self->create_table;
    return $self;
}

sub create_table {
    my $self = shift;
    my $exists = $self->{db}->db->query("SELECT name FROM sqlite_master WHERE type='table' AND name='torrents'")->array;

    unless ($exists) {
        $self->{db}->db->query(q{
            CREATE TABLE torrents (
                id TEXT PRIMARY KEY,
                description TEXT,
                episode TEXT,
                size TEXT,
                episode_number TEXT,
                show_name TEXT,
                link TEXT,
                date TEXT,
                magnet TEXT,
                group_name TEXT,
                group_link TEXT,
                rtoken TEXT,
                assigned_show_name TEXT,
                date_added INTEGER,
                assigned_timestamp INTEGER,
                season TEXT,
                season_number TEXT
            )
        });
        $self->create_indexes;
    }
}

sub create_indexes {
    my $self = shift;
    $self->{db}->db->query('CREATE INDEX idx_id_magnet ON torrents (id, magnet)');
    $self->{db}->db->query('CREATE INDEX idx_show_name ON torrents (show_name)');
    $self->{db}->db->query('CREATE INDEX idx_group_name ON torrents (group_name)');
}

sub get_not_queued {
    my ($self) = @_;
    # all episodes should have been downloaded within the last 100 days
    my $sql = q{
        SELECT t.*
        FROM torrents t
        WHERE NOT EXISTS (
            SELECT 1 FROM queued_torrents q 
            WHERE (q.show_name = t.assigned_show_name OR (t.id = q.torrent_id AND q.torrent_id != ''))
        )
        AND NOT EXISTS (
            SELECT 1 FROM torrents t2
            WHERE (t2.assigned_timestamp IS NOT NULL AND t2.assigned_timestamp != '')
            AND strftime('%s', 'now') - t2.assigned_timestamp > 24 * 3600 * 100
            AND t2.assigned_show_name = t.assigned_show_name
            AND t2.episode_number = t.episode_number
            AND t2.season_number = t.season_number
        )
        AND NOT EXISTS (
            SELECT 1 FROM blockers b
            WHERE (b.blocker_name = 'show_name' AND b.value = t.assigned_show_name)
            OR (b.blocker_name = 'id' AND b.value = t.id)
            OR (b.blocker_name = 'episode' AND b.value = t.episode)
            OR (b.blocker_name = 'group_name' AND b.value = t.group_name COLLATE NOCASE)
            OR (b.blocker_name = 'words' AND t.assigned_show_name LIKE '%' || b.value || '%')
            OR (b.blocker_name = 'words' AND t.regular_name LIKE '%' || b.value || '%')
            OR (b.blocker_name = 'season' AND b.value = t.season)
        );
    };
    return $self->{db}->db->query($sql)->hashes->to_array;
}

