#include <cuda_runtime.h>
#include <stdio.h>
#include <nvtx3/nvToolsExt.h>
#include <iostream>

#include "lud_kernel.h"

void checkCudaStatus(cudaError_t status, const char *message) {
    if (status != cudaSuccess) {
        std::cerr << message << ": " << cudaGetErrorString(status) << std::endl;
        exit(EXIT_FAILURE);
    }
}

void checkCublasStatus(cublasStatus_t status, const char *message) {
    if (status != CUBLAS_STATUS_SUCCESS) {
        std::cerr << message << std::endl;
        exit(EXIT_FAILURE);
    }
}

#define OFFSET(i, j, ld) ((i) * (ld) + (j))

#ifdef RD_WG_SIZE_0_0
#define BLOCK_SIZE RD_WG_SIZE_0_0
#elif defined(RD_WG_SIZE_0)
#define BLOCK_SIZE RD_WG_SIZE_0
#elif defined(RD_WG_SIZE)
#define BLOCK_SIZE RD_WG_SIZE
#else
#define BLOCK_SIZE 16
#endif

__global__ void lud_diagonal(float *m, int matrix_dim, int offset) {
    int i, j;
    __shared__ float shadow[BLOCK_SIZE][BLOCK_SIZE];

    // load the sub-matrix of size BLOCK_SIZE*BLOCK_SIZE at the diagonal
    // shadow[i][j] = m[offset+i][offset+j]
    int array_offset = offset * matrix_dim + offset;
    for (i = 0; i < BLOCK_SIZE; i++) {
        shadow[i][threadIdx.x] = m[array_offset + threadIdx.x];
        array_offset += matrix_dim;
    }
    __syncthreads();
    for (i = 0; i < BLOCK_SIZE - 1; i++) {
        // calculate the lower triangular matrix, where the diagonal values are
        // 1 and not stored
        if (threadIdx.x > i) {
            for (j = 0; j < i; j++)
                shadow[threadIdx.x][i] -= shadow[threadIdx.x][j] * shadow[j][i];
            shadow[threadIdx.x][i] /= shadow[i][i];
        }
        __syncthreads();

        // calculate the upper triangular matrix
        if (threadIdx.x > i) {
            for (j = 0; j < i + 1; j++)
                shadow[i + 1][threadIdx.x] -=
                    shadow[i + 1][j] * shadow[j][threadIdx.x];
        }
        __syncthreads();
    }

    /*
       The first row is not modified, it
       is no need to write it back to the
       global memory
    */
    array_offset = (offset + 1) * matrix_dim + offset;
    for (i = 1; i < BLOCK_SIZE; i++) {
        m[array_offset + threadIdx.x] = shadow[i][threadIdx.x];
        array_offset += matrix_dim;
    }
}

__global__ void lud_perimeter(float *m, int matrix_dim, int offset) {
    __shared__ float dia[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float peri_row[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float peri_col[BLOCK_SIZE][BLOCK_SIZE];

    int i, j, array_offset;
    int idx;

    // the actual block size of this kernel is 2*BLOCK_SIZE
    if (threadIdx.x < BLOCK_SIZE) {
        idx = threadIdx.x;

        // load the upper-half of the BS*BS diagonal
        // dia[i][j] = m[offset + i][offset + j] for i < BS/2 and j < BS
        array_offset = offset * matrix_dim + offset;
        for (i = 0; i < BLOCK_SIZE / 2; i++) {
            dia[i][idx] = m[array_offset + idx];
            array_offset += matrix_dim;
        }

        // load the rows right to the diagnal
        // peri_row[i][j] = m[offset + i][offset + (Bidx + 1) * BS + j]
        array_offset = offset * matrix_dim + offset;
        for (i = 0; i < BLOCK_SIZE; i++) {
            peri_row[i][idx] =
                m[array_offset + (blockIdx.x + 1) * BLOCK_SIZE + idx];
            array_offset += matrix_dim;
        }

    } else {
        idx = threadIdx.x - BLOCK_SIZE;

        // load the lower-half of the BS*BS diagonal
        // dia[i + BS/2][j] = m[offset + BS/2 + i][offset + j]
        // for i < BS/2 and j < BS
        array_offset = (offset + BLOCK_SIZE / 2) * matrix_dim + offset;
        for (i = BLOCK_SIZE / 2; i < BLOCK_SIZE; i++) {
            dia[i][idx] = m[array_offset + idx];
            array_offset += matrix_dim;
        }

        // load the columns below the diagnal
        // peri_col[i][j] = m[offset + (Bidx + 1) * BS + i][offset + j]
        array_offset =
            (offset + (blockIdx.x + 1) * BLOCK_SIZE) * matrix_dim + offset;
        for (i = 0; i < BLOCK_SIZE; i++) {
            peri_col[i][idx] = m[array_offset + idx];
            array_offset += matrix_dim;
        }
    }
    __syncthreads();

    /* this version works ok on hardware, but not gpgpusim
     **************************************************************
      if (threadIdx.x < BLOCK_SIZE) { //peri-row
        idx=threadIdx.x;
        for(i=1; i < BLOCK_SIZE; i++){
          for (j=0; j < i; j++)
            peri_row[i][idx]-=dia[i][j]*peri_row[j][idx];
        }


        array_offset = (offset+1)*matrix_dim+offset;
        for(i=1; i < BLOCK_SIZE; i++){
          m[array_offset+(blockIdx.x+1)*BLOCK_SIZE+idx] = peri_row[i][idx];
          array_offset += matrix_dim;
        }
      } else { //peri-col
        idx=threadIdx.x - BLOCK_SIZE;
        for(i=0; i < BLOCK_SIZE; i++){
          for(j=0; j < i; j++)
            peri_col[idx][i]-=peri_col[idx][j]*dia[j][i];
          peri_col[idx][i] /= dia[i][i];
        }

        __syncthreads();

        array_offset = (offset+(blockIdx.x+1)*BLOCK_SIZE)*matrix_dim+offset;
        for(i=0; i < BLOCK_SIZE; i++){
          m[array_offset+idx] =  peri_col[i][idx];
          array_offset += matrix_dim;
        }
      }
    ***************************************************************/
    if (threadIdx.x < BLOCK_SIZE) {  // peri-row
        // calculate the rows right to the diagonal (upper triangular)
        idx = threadIdx.x;
        for (i = 1; i < BLOCK_SIZE; i++) {
            for (j = 0; j < i; j++)
                peri_row[i][idx] -= dia[i][j] * peri_row[j][idx];
        }
    } else {  // peri-col
        // calculate the columns below the diagonal (lower triangular)
        idx = threadIdx.x - BLOCK_SIZE;
        for (i = 0; i < BLOCK_SIZE; i++) {
            for (j = 0; j < i; j++)
                peri_col[idx][i] -= peri_col[idx][j] * dia[j][i];
            peri_col[idx][i] /= dia[i][i];
        }
    }

    __syncthreads();

    // write back peri_row and peri_col
    if (threadIdx.x < BLOCK_SIZE) {  // peri-row
        idx = threadIdx.x;
        array_offset = (offset + 1) * matrix_dim + offset;
        for (i = 1; i < BLOCK_SIZE; i++) {
            m[array_offset + (blockIdx.x + 1) * BLOCK_SIZE + idx] =
                peri_row[i][idx];
            array_offset += matrix_dim;
        }
    } else {  // peri-col
        idx = threadIdx.x - BLOCK_SIZE;
        array_offset =
            (offset + (blockIdx.x + 1) * BLOCK_SIZE) * matrix_dim + offset;
        for (i = 0; i < BLOCK_SIZE; i++) {
            m[array_offset + idx] = peri_col[i][idx];
            array_offset += matrix_dim;
        }
    }
}

__global__ void lud_internal(float *m, int matrix_dim, int offset) {
    __shared__ float peri_row[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float peri_col[BLOCK_SIZE][BLOCK_SIZE];

    int i;
    float sum;

    int global_row_id = offset + (blockIdx.y + 1) * BLOCK_SIZE;
    int global_col_id = offset + (blockIdx.x + 1) * BLOCK_SIZE;

    peri_row[threadIdx.y][threadIdx.x] =
        m[(offset + threadIdx.y) * matrix_dim + global_col_id + threadIdx.x];
    peri_col[threadIdx.y][threadIdx.x] =
        m[(global_row_id + threadIdx.y) * matrix_dim + offset + threadIdx.x];

    __syncthreads();

    sum = 0;
    for (i = 0; i < BLOCK_SIZE; i++)
        sum += peri_col[threadIdx.y][i] * peri_row[i][threadIdx.x];
    m[(global_row_id + threadIdx.y) * matrix_dim + global_col_id +
      threadIdx.x] -= sum;
}


__global__ void lud_internal_residual(float *m, int matrix_dim, int offset) {
    __shared__ float peri_row[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float peri_col[BLOCK_SIZE][BLOCK_SIZE];

    int i;
    float sum;
    int global_row_id = offset + (blockIdx.y + 1) * BLOCK_SIZE;
    int global_col_id = offset + (blockIdx.x + 1) * BLOCK_SIZE;

    if (blockIdx.x > 0 || blockIdx.y > 0) {
        peri_row[threadIdx.y][threadIdx.x] =
            m[(offset + threadIdx.y) * matrix_dim + global_col_id + threadIdx.x];
        peri_col[threadIdx.y][threadIdx.x] =
            m[(global_row_id + threadIdx.y) * matrix_dim + offset + threadIdx.x];
    }

    __syncthreads();

    if (blockIdx.x > 0 || blockIdx.y > 0) {
        sum = 0;
        for (i = 0; i < BLOCK_SIZE; i++)
            sum += peri_col[threadIdx.y][i] * peri_row[i][threadIdx.x];
        m[(global_row_id + threadIdx.y) * matrix_dim + global_col_id +
        threadIdx.x] -= sum;
    }
}

void lud_cuda(float *m, int matrix_dim) {
    int i = 0;
    dim3 dimBlock(BLOCK_SIZE, BLOCK_SIZE);
    // float *m_debug = (float *)malloc(matrix_dim * matrix_dim *
    // sizeof(float));

    for (i = 0; i < matrix_dim - BLOCK_SIZE; i += BLOCK_SIZE) {
        // process the diagonal m[i : i+BLOCK_SIZE][i : i+BLOCK_SIZE]
        lud_diagonal<<<1, BLOCK_SIZE>>>(m, matrix_dim, i);
        // process m[i+BLOCK_SIZE : matrix_dim][i : i+BLOCK_SIZE] and
        // m[i : i+BLOCK_SIZE][i+BLOCK_SIZE : matrix_dim]
        lud_perimeter<<<(matrix_dim - i) / BLOCK_SIZE - 1, BLOCK_SIZE * 2>>>(
            m, matrix_dim, i);
        // process m[i+BLOCK_SIZE : matrix_dim][i+BLOCK_SIZE : matrix_dim]
        dim3 dimGrid((matrix_dim - i) / BLOCK_SIZE - 1,
                     (matrix_dim - i) / BLOCK_SIZE - 1);
        lud_internal<<<dimGrid, dimBlock>>>(m, matrix_dim, i);
    }
    lud_diagonal<<<1, BLOCK_SIZE>>>(m, matrix_dim, i);
}

// 2d tiling version of lud_diagonal
__global__ void lud_diagonal_v2(float *m, int matrix_dim, int offset) {
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Only one block is launched
    int row = ty;
    int col = tx;

    __shared__ float s_m[BLOCK_SIZE][BLOCK_SIZE];

    s_m[row][col] = m[OFFSET(row + offset, col + offset, matrix_dim)];
    __syncthreads();

    for (int k = 0; k < BLOCK_SIZE; k++) {
        // process the column m[offset : offset + BS][offset + k]
        if (row > k && col == k) {
            s_m[row][col] /= s_m[k][k];
        }
        __syncthreads();

        // process the sub-matrix m[offset : offset + BS][offset : offset + BS]
        if (row > k && col > k) {
            s_m[row][col] -= s_m[row][k] * s_m[k][col];
        }
        __syncthreads();
    }

    m[OFFSET(row + offset, col + offset, matrix_dim)] = s_m[row][col];
}

// 2d tiling version of lud_perimeter
__global__ void lud_perimeter_v2(float *m, int matrix_dim, int offset, int col_blocks) {
    int bx = blockIdx.x;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    bool at_col = (bx < col_blocks);
    int row;
    int col;

    if (at_col) {
        // block id < col_blocks process the columns below the diagonal
        row = (bx + 1) * BLOCK_SIZE + ty;
        col = tx;
    }
    else {
        // block id >= col_blocks process the rows right to the diagonal
        row = ty;
        col = (bx - col_blocks + 1) * BLOCK_SIZE + tx;
    }

    __shared__ float s_dia[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float s_peri[BLOCK_SIZE][BLOCK_SIZE];

    // load the diagonal and perimeter sub-matrix
    s_dia[ty][tx] = m[OFFSET(ty + offset, tx + offset, matrix_dim)];
    s_peri[ty][tx] = m[OFFSET(row + offset, col + offset, matrix_dim)];
    __syncthreads();

    for (int k = 0; k < BLOCK_SIZE; k++) {
        // process the column m[offset : matrix_dim][offset + k]
        if (at_col && col == k) {
            s_peri[ty][tx] /= s_dia[k][k];
        }
        __syncthreads();

        // process the submatrix at the column (lower triangular)
        if (at_col && col > k) {
            s_peri[ty][tx] -= s_peri[ty][k] * s_dia[k][tx];
        }

        // process the submatrix at the row (upper triangular)
        if (!at_col && row > k) {
            s_peri[ty][tx] -= s_dia[ty][k] * s_peri[k][tx];
        }
        __syncthreads();
    }

    // write back the perimeter sub-matrix
    m[OFFSET(row + offset, col + offset, matrix_dim)] = s_peri[ty][tx];
}

// fuse the internal kernel with the next diagonal kernel
__global__ void lud_internal_diagonal_fused(float *m, int matrix_dim, int offset) {
    __shared__ float peri_row[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float peri_col[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float s_m[BLOCK_SIZE][BLOCK_SIZE];

    int i;
    float sum;

    int global_row_id = offset + (blockIdx.y + 1) * BLOCK_SIZE;
    int global_col_id = offset + (blockIdx.x + 1) * BLOCK_SIZE;

    peri_row[threadIdx.y][threadIdx.x] =
        m[(offset + threadIdx.y) * matrix_dim + global_col_id + threadIdx.x];
    peri_col[threadIdx.y][threadIdx.x] =
        m[(global_row_id + threadIdx.y) * matrix_dim + offset + threadIdx.x];

    __syncthreads();

    sum = 0;
    for (i = 0; i < BLOCK_SIZE; i++)
        sum += peri_col[threadIdx.y][i] * peri_row[i][threadIdx.x];

    // process the next diagonal
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = ty;
    int col = tx;

    s_m[row][col] = m[OFFSET(global_row_id + row, global_col_id + col, matrix_dim)];
    s_m[row][col] -= sum;
    __syncthreads();

    for (int k = 0; k < BLOCK_SIZE; k++) {
        // process the column m[offset : offset + BS][offset + k]
        if (row > k && col == k) {
            s_m[row][col] /= s_m[k][k];
        }
        __syncthreads();

        // process the sub-matrix m[offset : offset + BS][offset : offset + BS]
        if (row > k && col > k) {
            s_m[row][col] -= s_m[row][k] * s_m[k][col];
        }
        __syncthreads();
    }

    m[OFFSET(global_row_id + row, global_col_id + col, matrix_dim)] = s_m[row][col];
}

// lud_cuda wrapper
void lud_cuda_wrapper(float *m, float *d_m, int matrix_dim,
                      float *kernel_time) {
    checkCudaStatus(cudaMemcpy(d_m, m, matrix_dim * matrix_dim * sizeof(float),
                               cudaMemcpyHostToDevice),
                    "Failed to copy matrix to device");
    // sync cudaMemcpy
    checkCudaStatus(cudaDeviceSynchronize(), "Failed to synchronize device");

    stopwatch timer;
    stopwatch_start(&timer);
    nvtxRangePush("lud_rodiana");
    lud_cuda(d_m, matrix_dim);
    checkCudaStatus(cudaGetLastError(), "Failed to launch kernel");
    checkCudaStatus(cudaDeviceSynchronize(), "Failed to synchronize device");
    nvtxRangePop();
    stopwatch_stop(&timer);
    *kernel_time = get_interval_by_sec(&timer) * 1000;

    checkCudaStatus(cudaMemcpy(m, d_m, matrix_dim * matrix_dim * sizeof(float),
                               cudaMemcpyDeviceToHost),
                    "Failed to copy matrix back to host");
}

// cublas getrf wrapper
void lud_cublas_wrapper(float *m, float *d_m, int matrix_dim,
                        float *kernel_time) {
    // cublasSgetrfBatched requires the matrix to be stored in column-major
    // order so we need to transpose the matrix
    float *m_col_major =
        (float *)malloc(matrix_dim * matrix_dim * sizeof(float));
    for (int i = 0; i < matrix_dim; i++) {
        for (int j = 0; j < matrix_dim; j++) {
            m_col_major[j * matrix_dim + i] = m[i * matrix_dim + j];
        }
    }

    cublasHandle_t handle;
    checkCublasStatus(cublasCreate(&handle), "Failed to create cuBLAS handle");

    int *d_info;
    checkCudaStatus(cudaMalloc((void **)&d_info, sizeof(int)),
                    "Failed to allocate device memory for info");

    // Create array of pointers for batched operation
    float **d_Marray;
    checkCudaStatus(cudaMalloc((void **)&d_Marray, sizeof(float *)),
                    "Failed to allocate device memory for d_Marray");
    checkCudaStatus(
        cudaMemcpy(d_Marray, &d_m, sizeof(float *), cudaMemcpyHostToDevice),
        "Failed to copy d_A to d_Marray");

    checkCudaStatus(
        cudaMemcpy(d_m, m_col_major, matrix_dim * matrix_dim * sizeof(float),
                   cudaMemcpyHostToDevice),
        "Failed to copy matrix to device");
    // sync cudaMemcpy
    checkCudaStatus(cudaDeviceSynchronize(), "Failed to synchronize device");

    stopwatch timer;
    stopwatch_start(&timer);
    nvtxRangePush("lud_cublas");
    checkCublasStatus(cublasSgetrfBatched(handle, matrix_dim, d_Marray,
                                          matrix_dim, NULL, d_info, 1),
                      "Failed to perform LU decomposition");
    checkCudaStatus(cudaGetLastError(), "Failed to launch kernel");
    checkCudaStatus(cudaDeviceSynchronize(), "Failed to synchronize device");
    nvtxRangePop();
    stopwatch_stop(&timer);
    *kernel_time = get_interval_by_sec(&timer) * 1000;

    checkCudaStatus(
        cudaMemcpy(m_col_major, d_m, matrix_dim * matrix_dim * sizeof(float),
                   cudaMemcpyDeviceToHost),
        "Failed to copy matrix back to host");

    // transpose the matrix back
    for (int i = 0; i < matrix_dim; i++) {
        for (int j = 0; j < matrix_dim; j++) {
            m[i * matrix_dim + j] = m_col_major[j * matrix_dim + i];
        }
    }
}

// wrapper for 2d tiling kernels
void lud_v2_wrapper(float *m, float *d_m, int matrix_dim, float *kernel_time) {
    checkCudaStatus(cudaMemcpy(d_m, m, matrix_dim * matrix_dim * sizeof(float),
                               cudaMemcpyHostToDevice),
                    "Failed to copy matrix to device");
    // sync cudaMemcpy
    checkCudaStatus(cudaDeviceSynchronize(), "Failed to synchronize device");

    stopwatch timer;
    stopwatch_start(&timer);
    nvtxRangePush("lud_opt");

    int i = 0;
    dim3 dimBlock(BLOCK_SIZE, BLOCK_SIZE);

    for (i = 0; i < matrix_dim - BLOCK_SIZE; i += BLOCK_SIZE) {

        // process the diagonal m[i : i+BLOCK_SIZE][i : i+BLOCK_SIZE]
        lud_diagonal_v2<<<1, dimBlock>>>(d_m, matrix_dim, i);

        // process m[i+BLOCK_SIZE : matrix_dim][i : i+BLOCK_SIZE] and
        // m[i : i+BLOCK_SIZE][i+BLOCK_SIZE : matrix_dim]
        lud_perimeter_v2<<<((matrix_dim - i) / BLOCK_SIZE - 1) * 2, dimBlock>>>(
            d_m, matrix_dim, i, (matrix_dim - i) / BLOCK_SIZE - 1);

        // process m[i+BLOCK_SIZE : matrix_dim][i+BLOCK_SIZE : matrix_dim]
        dim3 dimGrid((matrix_dim - i) / BLOCK_SIZE - 1,
                     (matrix_dim - i) / BLOCK_SIZE - 1);
        lud_internal<<<dimGrid, dimBlock>>>(d_m, matrix_dim, i);
    }

    // process the last diagonal block
    lud_diagonal_v2<<<1, dimBlock>>>(d_m, matrix_dim, i);

    checkCudaStatus(cudaGetLastError(), "Failed to launch kernel");
    checkCudaStatus(cudaDeviceSynchronize(), "Failed to synchronize device");

    nvtxRangePop();
    stopwatch_stop(&timer);
    *kernel_time = get_interval_by_sec(&timer) * 1000;

    checkCudaStatus(cudaMemcpy(m, d_m, matrix_dim * matrix_dim * sizeof(float),
                               cudaMemcpyDeviceToHost),
                    "Failed to copy matrix back to host");
}

