use Parsley::Time;

my @utilities = (
    {name => 'Update display descriptions', id => 'update_display_descriptions'},
    {name => 'Update empty gencoders', id => 'update_empty_gencoders'},
    {name => 'Update empty vencode', id => 'update_empty_vencode'},
    {name => 'Update networks', id => 'update_networks'},
    {name => 'Update assigned timestamps', id => 'update_assigned_timestamps'},
    {name => 'Update seasons', id => 'update_seasons'},
    {name => 'Update episodes', id => 'update_episodes'},
    {name => 'Update regular names', id => 'update_regular_names'},
    {name => 'Update sizes', id => 'update_sizesar_names'},
    {name => 'Blockers purge', id => 'blockers_purge'},
);

sub add_routes($app) {
    $app->routes->get('/utilities' => \&GET_listing);
    $app->routes->get('/run/:id' => \&GET_run);
}

sub GET_listing($c) {
    my $content = $c->render_to_string(
        template => 'generic-table',
        rows => \@utilities,
        keys => ['name'],
        remove_link => '/run',
    );
    $c->render(template => 'main', content => $content);
};

sub GET_run($c) {
    my $id = $c->param('id');
    if ($id eq 'update_display_descriptions') {
        return GET_update_display_descriptions($c);
    }
    if ($id eq 'update_empty_gencoders') {
        return GET_update_empty_gencoders($c);
    }
    if ($id eq 'update_empty_vencode') {
        return GET_update_empty_vencode($c);
    }
    if ($id eq 'update_networks') {
        return GET_update_networks($c);
    }
    if ($id eq 'update_assigned_timestamps') {
        return GET_update_assigned_timestamps($c);
    }
    if ($id eq 'update_seasons') {
        return GET_update_seasons($c);
    }
    if ($id eq 'update_episodes') {
        return GET_update_episodes($c);
    }
    if ($id eq 'update_regular_names') {
        return GET_update_regular_names($c);
    }

