sub GET_update_display_descriptions ($c) {
    my $db = Mojo::SQLite->new("sqlite:".$ENV{DB_PATH});
    my $sth = $db->db->query(q{
        SELECT * FROM torrents;
    });
    while (my $torrent = $sth->hash) {
        my $display_description = Hebshti::create_display_description($torrent);
        next if $display_description eq $torrent->{display_description};
        $db->db->query(q{
            UPDATE torrents SET display_description = ?
            WHERE id = ?;
        }, $display_description, $torrent->{id});
    }
    return $c->render(json => {
        status => 'success',
        toast => 'Display descriptions updated',
    });
}

sub GET_update_empty_gencoders ($c) {
    my $db = DBTorrents->new($ENV{DB_PATH});
    $db->update_empty_gencoders();
    return $c->render(json => {
        status => 'success',
        toast => 'Gencoders updated',
    });
}

sub GET_update_empty_vencode ($c) {
    my $db = DBTorrents->new($ENV{DB_PATH});
    $db->update_empty_vencode();
    return $c->render(json => {
        status => 'success',
        toast => 'Vencodes updated',
    });
}

sub GET_update_networks ($c) {
    my $db = Mojo::SQLite->new("sqlite:".$ENV{DB_PATH});
    my $sth = $db->db->query(q{
        SELECT * FROM torrents;
    });
    while (my $torrent = $sth->hash) {
        my $network = Hebshti::get_network($torrent->{regular_name});
        if ($network) {
            $db->db->query(q{
                UPDATE torrents SET network = ?
                WHERE id = ?;
            }, $network, $torrent->{id});
        }
    }
    return $c->render(json => {
        status => 'success',
        toast => 'Networks updated',
    });
}

sub GET_update_assigned_timestamps ($c) {
    my $db = Mojo::SQLite->new("sqlite:".$ENV{DB_PATH});
    my $sth = $db->db->query(q{
        SELECT * FROM torrents
    });
    my $count = 0;
    while (my $torrent = $sth->hash) {
        my $relative_timestamp = Parsley::Time::epoch_from_date($torrent->{date}) || 
            Parsley::Time::epoch_from_relative_time($torrent->{date_added}, $torrent->{date});
        next if !$relative_timestamp;
        $count++;
        print $torrent->{date}, ' ', strftime("%H:%M %d%m%Y", localtime($relative_timestamp)), ' ',
            strftime("%H:%M %d%m%Y", localtime($torrent->{date_added})), "
";
        $db->db->query(q{
            UPDATE torrents SET assigned_timestamp = ?
            WHERE id = ?;
        }, $relative_timestamp, $torrent->{id});
    }
    return $c->render(json => {
        status => 'success',
        toast => "Assigned timestamps updated ($count)",
    });
}

sub GET_update_seasons ($c) {
    my $db = Mojo::SQLite->new("sqlite:".$ENV{DB_PATH});
    my $sth = $db->db->query(q{
        SELECT * FROM torrents 
        WHERE season IS NULL 
        OR season = '' 
        OR assigned_show_name IN (SELECT pattmain FROM patts)
    });
    while (my $torrent = $sth->hash) {
        my ($a_, $b_, $c_, $season_number) = Hebshti::parse_torrent_name($torrent->{description});
        if ($season_number) {
            my $season = $torrent->{assigned_show_name}.'##'.$season_number;
            $db->db->query(q{
                UPDATE torrents SET season = ?, season_number = ?
                WHERE id = ?;
            }, $season, $season_number, $torrent->{id});
        }
    }
    return $c->render(json => {
        status => 'success',
        toast => 'Seasons updated',
    });
}

sub GET_update_episodes ($c) {
    my $db = Mojo::SQLite->new("sqlite:".$ENV{DB_PATH});
    my $sth = $db->db->query(q{
        SELECT * FROM torrents
        WHERE episode IS NULL 
        OR episode = ''
        OR assigned_show_name IN (SELECT pattmain FROM patts)
    });
    while (my $torrent = $sth->hash) {
        my ($a_, $b_, $episode_number, $d_) = Hebshti::parse_torrent_name($torrent->{description});
        if ($episode_number) {
            my $episode = $torrent->{assigned_show_name}.'##'.$episode_number;
            $db->db->query(q{
                UPDATE torrents SET episode = ?, episode_number = ?
                WHERE id = ?;
            }, $episode, $episode_number, $torrent->{id});
        }   
    }
    return $c->render(json => {
        status => 'success',
        toast => 'Episodes updated',
    });
}

sub GET_blockers_purge ($c) {
    my $db = DBTorrents->new($ENV{DB_PATH});
    $db->purge_blockers();
    return $c->render(json => {
        status => 'success',
        toast => 'Blockers purged',
    });
}

sub GET_update_regular_names ($c) {
    my $db = Mojo::SQLite->new("sqlite:".$ENV{DB_PATH});
    my $sth = $db->db->query(q{SELECT * FROM torrents});
    while (my $torrent = $sth->hash) {
        my $s = Hebshti::synthesize($torrent);
        next if (
            defined $torrent->{season_number}
            && $s->{regular_name} eq $torrent->{regular_name}
            && $s->{season_number} eq $torrent->{season_number}
            && "$s->{episode_number}" eq $torrent->{episode_number}
            && $s->{assigned_show_name} eq $torrent->{assigned_show_name}
            && $s->{show_name} eq $torrent->{show_name}
        );
        $db->db->query(
            q{
                UPDATE torrents SET 
                    regular_name = ?,
                    season_number = ?,
                    season = ?,
                    episode_number = ?,
                    episode = ?,
                    show_name = ?,
                    assigned_show_name = ?
                WHERE id = ?;
            }, 
            $s->{regular_name}, 
            $s->{season_number},
            $s->{season},
            $s->{episode_number},
            $s->{episode},
            $s->{show_name},
            $s->{assigned_show_name},
            $torrent->{id}
        );
    }
    return $c->render(json => {
        status => 'success',
        toast => 'Names updated',
    });
}
