    def get_tags_df(self) -> pd.DataFrame:
        """Get the tags as a pandas DataFrame."""
        tags = self.tags
        tags_df = pd.DataFrame.from_dict({tag_id: tag.to_dict() for tag_id,tag in tags.items()}, orient='index')
        tags_df['subnet'] = pd.Categorical(tags_df['subnet'], categories=self.subnets.keys())
        tags_df.sort_values(by='subnet', ascending=True, inplace=True)
        return tags_df

    # Tags can have a subnet property. A subnet is a group of tags that are related to each other.
    def load_subnets(self) -> Dict[str, List['Tag']]:
        """Load the subnets from the tags.json file.
        Subnets are groups of Tags that share the same subnet property.
        """
        subnets = {}
        for tag in self.tags.values():
            if tag.subnet:
                if tag.subnet not in subnets:
                    subnets[tag.subnet] = []
                subnets[tag.subnet].append(tag)
        self._subnets = subnets
        self._sort_subnets()
        return subnets

    def _sort_subnets(self) -> None:
        """Sort the subnets by name."""
        def subnet_sort_key(subnet):
            if subnet == "primary":
                return (0, subnet)
            elif subnet == "weather":
                return (1, subnet)
            elif subnet == "other":
                return (3, subnet)
            else:
                return (2, subnet)

        self._subnets = dict(sorted(self._subnets.items(), key=lambda item: subnet_sort_key(item[0])))
        return self._subnets

    def show_subnets(self) -> None:
        """
        Print the subnets (by subnet name order) and their tags.
        """

        sorted_subnets = self.sort_subnets()

        for subnet, tags in sorted_subnets:
            print(f"Subnet: {subnet}")
            for tag in tags:
