class Tag:
    """Class representing a tag with caching capabilities.
    Tag data are stored in CSV files named "YYYY-MM.csv" in the tag folder.
    With columns :
    - ts : timestamp in ms
    - value : the value of the tag
    - quality (optional) : the quality of the tag (TODO: describe)
    """
    _tags_cache = {}
    _tags_cache_mtime = {}

    def __init__(self, building: Building, tag_id: str):
        self.building = building
        self.tag_id = tag_id.lower()
        # Initialize all properties to None
        self.name = None
        self.tag_type = None
        self.subnet = None
        self.unit = None
        self.value_type = None

        self._load_tags_config()

        if not self.tag_data_exists():
            raise ValueError(f"No data found for tag {self.tag_id} in building {self.building.path}")

        tags = Tag._tags_cache[self.building.path]
        if self.tag_id in tags:
            for prop in TAG_PROPERTIES:
                setattr(self, prop, tags[self.tag_id].get(prop))

    def _load_tags_config(self) -> None:
        """Load the tags config file if it has changed."""
        tags_config_path = os.path.join(BASE_DIR, "data", "building", self.building.path, "tags.json")
        current_mtime = os.path.getmtime(tags_config_path) if os.path.exists(tags_config_path) else None
        # Load the tags config file if it has changed
        if self.building.path not in Tag._tags_cache or Tag._tags_cache_mtime.get(self.building.path) != current_mtime:
            if has_tags_config(self.building.path):
                Tag._tags_cache[self.building.path] = get_tags_config(self.building.path)
                Tag._tags_cache_mtime[self.building.path] = current_mtime
            else:
                logger.warning(f"No tags.json file found for building {self.building.path}")
                Tag._tags_cache[self.building.path] = {}
                Tag._tags_cache_mtime[self.building.path] = None
        else:
            logger.info(f"Using cached tags for building {self.building.path}")

        # Check if the tag data exists, if not, raise an error
        if not self.tag_data_exists():
            raise ValueError(f"No data found for tag {self.tag_id} in building {self.building.path}")

        # Update the tag properties with the values from the tags config file
        tags = Tag._tags_cache[self.building.path]
        if self.tag_id in tags:
            for prop in TAG_PROPERTIES:
                setattr(self, prop, tags[self.tag_id].get(prop))

    def set_name(self, name: str):
        self.name = name

    def set_tag_type(self, tag_type: str):
        self.tag_type = tag_type

    def set_subnet(self, subnet: str):
        self.subnet = subnet

    def set_unit(self, unit: str):
        self.unit = unit

    def set_value_type(self, value_type: str):
        self.value_type = value_type

    def tag_data_exists(self) -> bool:
        tag_path = os.path.join(BASE_DIR, "data", "building", self.building.path, self.tag_id)
        if os.path.isdir(tag_path) and not any(os.path.isdir(os.path.join(tag_path, d))
                                               for d in os.listdir(tag_path)):
            return True
        return False

    def _get_raw_data(self, from_date: str = None, to_date: str = None) -> pd.DataFrame:
        """Get the data for the tag from the database.
        Raw data are stored in separate CSV files for each month as "YYYY-MM.csv".
        This method read all the CSV files for the given range and return a pandas DataFrame.
        """
        tag_path = os.path.join(BASE_DIR, "data", "building", self.building.path, self.tag_id)
        # Get all the CSV files for the given range
        csv_files = [f for f in os.listdir(tag_path) if f.endswith(".csv")]
        csv_files = [f for f in csv_files if f[4]=='-']
        if from_date:
            if isinstance(from_date, datetime):
                # convert datetime to date string
                from_date = from_date.date().strftime("%Y-%m")
            elif isinstance(from_date, str):
                pass
            else:
                raise ValueError("from_date must be a string or a datetime object")

            from_month = from_date[:7]
            csv_files = [f for f in csv_files if f[:7] >= from_month]
        if to_date:
            if isinstance(to_date, datetime):
                # convert datetime to date string
                to_date = to_date.date().strftime("%Y-%m")
            elif isinstance(from_date, str):
                pass
            else:
                raise ValueError("to_date must be a string or a datetime object")

            to_month = to_date[:7]
            csv_files = [f for f in csv_files if f[:7] <= to_month]
        # add the month to each dataframe
        df = pd.concat([pd.read_csv(os.path.join(tag_path, f)).assign(month=f[:7])
                        for f in csv_files])
        df['datetime'] = pd.to_datetime(df['ts'], unit='ms')
        # df = df.sort_values(by="ts", ascending=True)
        # df = df.drop_duplicates(subset="ts", keep="first")
        return df

    def _check_month_bounds(self, row):
        if str(row['datetime'])[:7] == row['month']:
            return True

        date_and_time = datetime.fromtimestamp(row['ts'] / 1000, tz=pytz.utc)
        month_start = datetime(int(row['month'][:4]), int(row['month'][5:7]), 1, tzinfo=pytz.utc)

        if date_and_time < month_start:
            ecart = month_start - date_and_time
            if ecart.days > 1:
                return False
            else:
                return True

        next_month_start = month_start.replace(day=1) + pd.DateOffset(months=1)
        if date_and_time > next_month_start:
            ecart = date_and_time - next_month_start
            if ecart.days > 1:
                return False
            else:
                return True

        raise ValueError(f"Row {row} is not a valid date for month {row['month']}")

