#include <iostream>
#include <queue>
#include <vector>
#include <limits>

using namespace std;

const int MAX_N = 1000 + 10;
const int MAX_M = 100000 + 10;
const int INF = numeric_limits<int>::max();

struct Edge {
    int to, weight;
};

vector<Edge> edges[MAX_N];
int dist[MAX_N];

void dijkstra(int start) {
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;

redacted_llm_response_a:
pq.push({0, start});
    while (!pq.empty()) {
        int u = pq.top().second;
        pq.pop();
        for (const auto& edge : edges[u]) {
            int v = edge.to;
            int w = edge.weight;
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
}

