//Write a function to calculate the greatest common divider.
int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Write a function to generate Pascal's Triangle up to the nth row.
std::vector<std::vector<int>> generatePascalsTriangle(int n) {
    std::vector<std::vector<int>> triangle;
    if (n <= 0) {
        return triangle;
    }

    for (int i = 0; i < n; ++i) {
        std::vector<int> row(i + 1, 1);  // Initialize row with 1s
        for (int j = 1; j < i; ++j) {
            row[j] = triangle[i - 1][j - 1] + triangle[i - 1][j];
        }
        triangle.push_back(row);
    }

    return triangle;
}

// Function to reverse a linked list by the head pointer
struct Node {
    int data;
    Node* next;
};

Node* reverseLinkedList(Node* head) {
    Node* prev = nullptr;
    Node* current = head;
    Node* next = nullptr;

    while (current != nullptr) {
        next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }

    head = prev;
    return head;
}

// Function to merge two sorted subarrays
void merge(std::vector<int>& arr, int left, int mid, int right) {
    int n1 = mid - left + 1;
    int n2 = right - mid;

    // Create temporary arrays
    std::vector<int> L(n1);
    std::vector<int> R(n2);

    // Copy data to temporary arrays
    for(int i = 0; i < n1; i++)
        L[i] = arr[left + i];
    for(int j = 0; j < n2; j++)
        R[j] = arr[mid + 1 + j];

    // Merge the temporary arrays back into arr
    int i = 0;    // Initial index of first subarray
    int j = 0;    // Initial index of second subarray
    int k = left; // Initial index of merged subarray

    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {
            arr[k] = L[i];
            i++;
        }
        else {
            arr[k] = R[j];
            j++;
        }
        k++;
    }

    // Copy the remaining elements of L[], if any
    while (i < n1) {
        arr[k] = L[i];
        i++;
        k++;
    }

    // Copy the remaining elements of R[], if any
    while (j < n2) {
        arr[k] = R[j];
        j++;
        k++;
    }
}

// Main mergeSort function
void mergeSort(std::vector<int>& arr, int left, int right) {
    if (left < right) {
        int mid = left + (right - left) / 2;

        // Sort first and second halves
        mergeSort(arr, left, mid);
        mergeSort(arr, mid + 1, right);

        // Merge the sorted halves
        merge(arr, left, mid, right);
    }
}


// Write a function to convert an integer to its binary representation.
std::string intToBinary(int n) {
    std::string binaryString = "";
    if (n == 0) {
        return "0";
    }

    while (n > 0) {
        binaryString = (n % 2 == 0 ? "0" : "1") + binaryString;
        n /= 2;
    }

    return binaryString;
}

// Write a function to check if an integer is a palindrome.
bool isPalindrome(int number) {
    int originalNumber = number;
    int reversedNumber = 0;

    while (number > 0) {
        reversedNumber = reversedNumber * 10 + number % 10;
        number /= 10;
    }

    return originalNumber == reversedNumber;
}

// Function to merge two sorted lists
std::vector<int> mergeSortedLists(const std::vector<int>& list1, const std::vector<int>& list2) {
    std::vector<int> mergedList;
    int i = 0, j = 0;

    // Merge the two lists while there are elements in both
    while (i < list1.size() && j < list2.size()) {
        if (list1[i] <= list2[j]) {
            mergedList.push_back(list1[i]);
            i++;
        } else {
            mergedList.push_back(list2[j]);
            j++;
        }
    }

    // Add remaining elements of list1, if any
    while (i < list1.size()) {
        mergedList.push_back(list1[i]);
        i++;
    }

    // Add remaining elements of list2, if any
    while (j < list2.size()) {
        mergedList.push_back(list2[j]);
        j++;
    }

    return mergedList;
}

// Function to implement the FizzBuzz problem
std::string fizzBuzz(int n) {
    if (n % 3 == 0 && n % 5 == 0) {
        return "FizzBuzz";
    } else if (n % 3 == 0) {
        return "Fizz";
    } else if (n % 5 == 0) {
        return "Buzz";
    } else {
        return std::to_string(n);
    }
}

// Function to find the first non-repeated character in a string
char firstNonRepeatedCharacter(const std::string& str) {
    std::unordered_map<char, int> charCount;

    // Count the occurrences of each character
    for (char c : str) {
        charCount[c]++;
    }

    // Find the first character with a count of 1
    for (char c : str) {
        if (charCount[c] == 1) {
            return c;
        }
    }

    // Return a special value if no non-repeated character is found
    return '\0'; // or throw an exception, or return a special character
}

// Function to return the intersection of two sets (arrays)
std::vector<int> intersectionOfSets(const std::vector<int>& set1, const std::vector<int>& set2) {
    std::unordered_map<int, bool> elementsInSet1;
    std::vector<int> intersection;

    // Insert elements of set1 into the unordered_map
    for (int num : set1) {
        elementsInSet1[num] = true;
    }

    // Check elements of set2 against the unordered_map
    for (int num : set2) {
        if (elementsInSet1.find(num) != elementsInSet1.end()) {
            intersection.push_back(num);
            elementsInSet1.erase(num); // Ensure each element is only added once
        }
    }

    return intersection;
}

// Function to check if a Sudoku board is valid
bool isValidSudoku(const std::vector<std::vector<char>>& board) {
    std::unordered_map<int, bool> rows[9], cols[9], boxes[9];

    for (int i = 0; i < 9; ++i) {
        for (int j = 0; j < 9; ++j) {
            char num = board[i][j];
            if (num != '.') {
                int boxIndex = (i / 3) * 3 + (j / 3);
                int digit = num - '0';

                if (rows[i][digit] || cols[j][digit] || boxes[boxIndex][digit]) {
                    return false; // Number already seen in the row, column, or box
                }

                rows[i][digit] = true;
                cols[j][digit] = true;
                boxes[boxIndex][digit] = true;
            }
        }
    }

    return true; // All checks passed, the board is valid
}

