struct HasUnsealedAnnulusSpace {
  explicit HasUnsealedAnnulusSpace(WellUnsealedLogicConfig config) :
      config{std::move(config)} {};

  bool exists_insert_number_two(
      const InsertNumberTwoActionState& insert_number_two_state) const {
    return (insert_number_two_state ==
            InsertNumberTwoActionState::JUST_PLACED) ||
           (insert_number_two_state ==
            InsertNumberTwoActionState::EXISTS_INSERT);
  }

  bool is_side_rods_open(
      const ChristmasTreePreventer& preventer, bool is_left_side) const {
    if (is_left_side) {
      return (preventer.left_rods.rods_open_states.state_up ==
              RodsOpenState::OPEN) &&
             (preventer.left_rods.rods_open_states.state_down ==
              RodsOpenState::OPEN);
    }
    return (preventer.right_rods.rods_open_states.state_up ==
            RodsOpenState::OPEN) &&
           (preventer.right_rods.rods_open_states.state_down ==
            RodsOpenState::OPEN);
  }

  bool is_side_rods_open(const ChristmasTree& tree, bool is_left_side) const {
    if (!tree.parts.preventer.has_value())
      return false;
    return is_side_rods_open(tree.parts.preventer.value(), is_left_side);
  }

  bool is_side_rods_open(
      const std::vector<ChristmasTree>& trees, bool is_left_side) const {
    bool is_any_side_rods_open =
        std::any_of(trees.begin(), trees.end(), [&](const ChristmasTree& tree) {
          return is_side_rods_open(tree, is_left_side);
        });
    return is_any_side_rods_open;
  }

  bool operator()(
      const std::vector<ChristmasTree>& trees,
      const ChristmasTreeRodActionState& left_rod_action_state,
      const ChristmasTreeRodActionState& right_rod_action_state,
      const InsertNumberTwoActionState& insert_number_two_state) const {

    if (exists_insert_number_two(insert_number_two_state)) {
      return false;
    }
    if (this->config.define_rod_status_by_boxes) {
      bool is_left_side_rods_open = is_side_rods_open(trees, true);
      bool is_right_side_rods_open = is_side_rods_open(trees, false);

      return is_left_side_rods_open || is_right_side_rods_open;
    }
    return count_sealed_rods(left_rod_action_state, right_rod_action_state) <
           (this->config.require_only_one_rod_sealed ? 1 : 2);
  }

  WellUnsealedLogicConfig config;
};

