        config.person_missing_hysteresis)} {
}

std::vector<ScenarioLogicResult> WellUnsealedScenarioLogic::process(
    const std::unordered_map<stream_id_t, RecognitionStateSP>&
        recognition_states) {

  this->state->tiw_valve_action.push_recognition_states(recognition_states);
  const auto tiw_valve_action_state =
      this->state->tiw_valve_action.get_current_action_state();
  visualize_tiw_action_state(
      recognition_states,
      this->config.tiw_valve_action.person_zone,
      tiw_valve_action_state,
      this->config.log_action_state);

  this->state->insert_number_two_action.push_recognition_states(
      recognition_states);
  const auto insert_number_two_state =
      this->state->insert_number_two_action.get_current_action_state();
  visualize_insert_number_two_action_state(
      recognition_states,
      this->config.tiw_valve_action.person_zone,
      insert_number_two_state,
      this->config.log_action_state);

  const auto left_rod_action_state = process_rods(
      recognition_states,
      this->state->left_rod_action,
      ChristmasTreeRodActionMode::LEFT,
      this->config.rod_action.required_zone_visualize_rods_state,
      this->config.log_action_state);
  const auto right_rod_action_state = process_rods(
      recognition_states,
      this->state->right_rod_action,
      ChristmasTreeRodActionMode::RIGHT,
      this->config.rod_action.required_zone_visualize_rods_state,
      this->config.log_action_state);

  // extract_christmas_trees(recognition_states)

  const bool exists_insert_number_two =
      (insert_number_two_state == InsertNumberTwoActionState::JUST_PLACED) ||
      (insert_number_two_state == InsertNumberTwoActionState::EXISTS_INSERT);

  const bool pipe_lifting_started =
      exists_state(recognition_states, has_pipe_lifting_started);

  const timestamp_t current_ts =
      extract_last_known_timestamp(recognition_states);
  const bool exists_human_not_integrated =
      exists_state(recognition_states, has_humans);
  this->state->person_missing_hysteresis->push_to_memory(
      current_ts, !exists_human_not_integrated);
  const bool person_missing_for_a_while =
      this->state->person_missing_hysteresis->is_event_present();

  const bool tubing_space_unsealed =
      tiw_valve_action_state == TiwValveActionState::NO_TIW_VALVE ||
      tiw_valve_action_state == TiwValveActionState::JUST_OPENED ||
      tiw_valve_action_state == TiwValveActionState::OPEN;
  const bool annulus_space_unsealed =
      count_sealed_rods(left_rod_action_state, right_rod_action_state) <
      (this->config.require_only_one_rod_sealed ? 1 : 2);

  const bool christmas_tree_has_preventer =
      exists_state(recognition_states, has_preventer);
  const bool has_christmas_tree_zone =
      exists_state(recognition_states, HasZone(Zone2DName::CHRISTMAS_TREE));
  const bool has_can_have_pipe_tkrs_zone =
      exists_state(recognition_states, HasZone(Zone2DName::CAN_HAVE_PIPE_TKRS));
  const bool all_cameras_are_in_correct_place =
      has_christmas_tree_zone && has_can_have_pipe_tkrs_zone;

  std::vector<ScenarioLogicResult> result;
  if ((tubing_space_unsealed || annulus_space_unsealed) &&
      !exists_insert_number_two && !pipe_lifting_started &&
      person_missing_for_a_while && christmas_tree_has_preventer &&
      all_cameras_are_in_correct_place) {
