import java.util.*;

public class hashmapImplementation {
    static class HashCode<K, V>{ //generics -> we can use any data type for key and value.
        private class Node{
            K key;
            V value;

            public Node(K key, V value){
                this.key = key;
                this.value = value;
            }
        }

        private int n; //nodes
        private int N;
        private LinkedList<Node> buckets[]; //N = buckets.length   -> array of linkedlists

        @SuppressWarnings("unchecked")
        public HashCode() {
            this.N = 4;
            this.buckets = new LinkedList[4];
            for (int i = 0; i < buckets.length; i++) {
                buckets[i] = new LinkedList<>();
            }
        }

        private int hashFunction(K key){
            int bi = key.hashCode();
             return Math.abs(bi) % buckets.length;
        }

        private int searchInLL(K key, int bi){
            LinkedList<Node> ll = bucket[bi];
            int di = 0;
            for(int i = 0; i < ll.size(); i++){
                Node node = ll.get(i);
                if(node.key == key){
                    return di;
                }
                di++;
            }
            return -1;
        }

        private void rehash(){
            LinkedList<Node> oldBuckets[] = buckets;
            this.N = 2 * N;
            this.buckets = new LinkedList[N];
            for (int i = 0; i < buckets.length; i++) {
                buckets[i] = new LinkedList<>();
            }
            this.n = 0;

            //add nodes in new bucket
            for(LinkedList<Node> ll : oldBuckets){
                for(Node node : ll){
                    put(node.key, node.value);
                }
            }
        }


        public void put(K key, V value){
            int bi = hashFunction(key);
            int di = searchInLL(key, bi);

            if(di != -1){
                Node node = buckets[bi].get(di);
                node.value = value;
            }
            else{
                Node node = new Node(key, value);
                buckets[bi].add(node);
                n++;
            }

            double lambda = (double)n/N;
            if(lambda > 2.0){
                rehash();
            }
        }
    }

