import java.util.*;

public class heap {
    static class Heap{
        ArrayList<Integer> arr = new ArrayList<>();
        public void add(int data){
            //add at last idx;
            arr.add(data);

            int x = arr.size() - 1; // x is child index
            int par = (x - 1) / 2; // parent index

            while (arr.get(x) < arr.get(par)) { // min heap  //T.C -> O(log n)
                // swap
                int temp = arr.get(x);
                arr.set(x, arr.get(par)); 
                arr.set(par, temp);

                x = par;
                par = (x - 1) / 2;
            }
        }

        public int peek(){
            return arr.get(0);
        }     

        public int remove(){
            int data = arr.get(0);

            // step 1 - swap first and last
            int lastIdx = arr.size() - 1;
            arr.set(0, arr.get(lastIdx));
            arr.remove(lastIdx);

            // step 2 - fix heap
            int idx = 0;
            while(true){
                int leftIdx = 2 * idx + 1;
                int rightIdx = 2 * idx + 2;
                int minIdx = idx;

                if(leftIdx < arr.size() && arr.get(leftIdx) < arr.get(minIdx)){
                    minIdx = leftIdx;
                }

                if(rightIdx < arr.size() && arr.get(rightIdx) < arr.get(minIdx)){
                    minIdx = rightIdx;
                }
                if(idx == minIdx){
                    break;
                }

                // swap when minIdx value is changed.
                int temp = arr.get(idx);
                arr.set(idx, arr.get(minIdx));
                arr.set(minIdx, temp);

                idx = minIdx;
            }
            return data;
        }
    }

    public boolean isEmpty(Heap h) {
        return h.arr.size() == 0;
    }
    public static void main(String[] args){
        Heap h = new Heap();
        h.add(5);
        h.add(3);
        h.add(8);
        System.out.println(h.peek()); // Should print the minimum element

import java.util.*;

public class binarySearchTree {
    static class Node {
        int data; 
        Node left;
        Node right;

        Node(int data){
            this.data = data;
            left = null;
            right = null;
        }
    }

    public static Node insert(Node root, int value){
        if(root == null){
            return new Node(value);
        }
        if(value < root.data){
            root.left = insert(root.left, value);
        } else {
            root.right = insert(root.right, value);
        }
        return root;
    }

    public static boolean search(Node root, int key){
        if(root == null){
            return false;
        }
        if(root.data == key){
            return true;
        }
        if(key < root.data){
            return search(root.left, key);
        } else {
            return search(root.right, key);
        }
    }



    public void inOrder(Node root){
        if(root != null){
            inOrder(root.left);
            System.out.print(root.data + " ");
            inOrder(root.right);
        }
    } 
    public static Node delete(Node root, int val){
        if(root == null){
            return null;
        }

        if(val < root.data){
            root.left = delete(root.left, val);
        } else if(val > root.data){
            root.right = delete(root.right, val);
        } else { //val == root.data
            //case 1: leaf node
            if(root.left == null && root.right == null){
                return null;
            }

            //case 2: single child
            if(root.left == null){
                return root.right;
            }
            if(root.right == null){
                return root.left;
            }

            //case 3: both children
            Node IS = findInorderSuccessor(root.right);
            root.data = IS.data;
            root.right = delete(root.right, IS.data);
        }
        return root;
    }

    public static Node findInorderSuccessor(Node root){
        while(root.left != null){
            root = root.left;
        }
        return root;
    }

    public static void printInRange(Node root, int k1, int k2){
        if(root == null){
            return;
        }
        if(root.data >= k1 && root.data <= k2){
            printInRange(root.left, k1, k2);
            System.out.print(root.data + " ");
            printInRange(root.right, k1, k2);
        } else if(root.data < k1){
            printInRange(root.right, k1, k2);
        } else {
            printInRange(root.left, k1, k2);
        }
    }


    public static void main(String args[]){
        int values[] = { 8, 5, 3, 1, 4, 6, 10, 11, 14 };
        Node root = null;

        for(int value : values){
            root = insert(root, value);
        }
