void lud_cuda(float *m, int matrix_dim) {
    int i = 0;
    dim3 dimBlock(BLOCK_SIZE, BLOCK_SIZE);
    // float *m_debug = (float *)malloc(matrix_dim * matrix_dim *
    // sizeof(float));

    for (i = 0; i < matrix_dim - BLOCK_SIZE; i += BLOCK_SIZE) {
        // process the diagonal m[i : i+BLOCK_SIZE][i : i+BLOCK_SIZE]
        lud_diagonal<<<1, BLOCK_SIZE>>>(m, matrix_dim, i);
        // process m[i+BLOCK_SIZE : matrix_dim][i : i+BLOCK_SIZE] and
        // m[i : i+BLOCK_SIZE][i+BLOCK_SIZE : matrix_dim]
        lud_perimeter<<<(matrix_dim - i) / BLOCK_SIZE - 1, BLOCK_SIZE * 2>>>(
            m, matrix_dim, i);
        // process m[i+BLOCK_SIZE : matrix_dim][i+BLOCK_SIZE : matrix_dim]
        dim3 dimGrid((matrix_dim - i) / BLOCK_SIZE - 1,
                     (matrix_dim - i) / BLOCK_SIZE - 1);
        lud_internal<<<dimGrid, dimBlock>>>(m, matrix_dim, i);
    }
    lud_diagonal<<<1, BLOCK_SIZE>>>(m, matrix_dim, i);
}

// 2d tiling version of lud_diagonal
__global__ void lud_diagonal_v2(float *m, int matrix_dim, int offset) {
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Only one block is launched
    int row = ty;
    int col = tx;

    __shared__ float s_m[BLOCK_SIZE][BLOCK_SIZE];

    s_m[row][col] = m[OFFSET(row + offset, col + offset, matrix_dim)];
    __syncthreads();

    for (int k = 0; k < BLOCK_SIZE; k++) {
        // process the column m[offset : offset + BS][offset + k]
        if (row > k && col == k) {
            s_m[row][col] /= s_m[k][k];
        }
        __syncthreads();

        // process the sub-matrix m[offset : offset + BS][offset : offset + BS]
        if (row > k && col > k) {
            s_m[row][col] -= s_m[row][k] * s_m[k][col];
        }
        __syncthreads();
    }

    m[OFFSET(row + offset, col + offset, matrix_dim)] = s_m[row][col];
}

// block tiling shape = (BM, BN), block size = (BX, BY)
template <int BM, int BN, int BX, int BY>
__global__ void lud_diagonal_v3(float *m, int matrix_dim, int offset) {
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * blockDim.x + tx;

    static_assert(BM == BN, "BM must be equal to BN");
    static_assert(BM % BY == 0, "BM must be divisible by BY");
    static_assert(BN % BX == 0, "BN must be divisible by BX");
    static_assert(BN % 4 == 0, "BN must be divisible by 4");
    static_assert(BM * BN / BX / BY % 4 == 0,
                  "BM * BN must be divisible by 4 * BX * BY");
    constexpr int tm = BM / BY;  // thread tile size at row
    constexpr int tn = BN / BX;  // thread tile size at col
    int row = ty * tm;
    int col = tx * tn;

    // each thread read 4 floats (float4) at a time
    int s_row = tid * 4 / BN;
    int s_col = tid * 4 % BN;
    constexpr int s_row_stride = 4 * BX * BY / BN;

    __shared__ float s_m[BM][BN];

    // load global memory to shared memory
    for (int i = s_row; i < BM; i += s_row_stride) {
        FETCH_FLOAT4(s_m[i][s_col]) =
            FETCH_FLOAT4(m[OFFSET(i + offset, s_col + offset, matrix_dim)]);
    }
    __syncthreads();

    for (int k = 0; k < BM; k++) {
        // process the column m[offset : offset + BS][offset + k]
        if (k >= col && k < col + tn) {
            float diag_k = s_m[k][k];
            for (int i = max(row, k + 1); i < row + tm; i++) {
                s_m[i][k] /= diag_k;
            }
        }
        __syncthreads();

        // process the sub-matrix m[offset : offset + BS][offset : offset + BS]
        if (k + 1 < row + tm && k + 1 < col + tn) {
            float reg_row[tm];
            float reg_col[tm];
            // load row and col registers
            for (int i = max(row, k + 1); i < row + tm; i++) {
                reg_row[i - row] = s_m[i][k];
            }
            for (int j = max(col, k + 1); j < col + tn; j++) {
                reg_col[j - col] = s_m[k][j];
            }
            for (int i = max(row, k + 1); i < row + tm; i++) {
                for (int j = max(col, k + 1); j < col + tn; j++) {
                    s_m[i][j] -= reg_row[i - row] * reg_col[j - col];
                }
            }
        }
        __syncthreads();
    }

    // write back to global memory
    for (int i = s_row; i < BM; i += s_row_stride) {
        FETCH_FLOAT4(m[OFFSET(i + offset, s_col + offset, matrix_dim)]) =
            FETCH_FLOAT4(s_m[i][s_col]);
    }
}

// 2d tiling version of lud_perimeter
__global__ void lud_perimeter_v2(float *m, int matrix_dim, int offset,
                                 int col_blocks) {
    int bx = blockIdx.x;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    bool at_col = (bx < col_blocks);
    int row;
    int col;

    if (at_col) {
        // block id < col_blocks process the columns below the diagonal
        row = (bx + 1) * BLOCK_SIZE + ty;
        col = tx;
    } else {
        // block id >= col_blocks process the rows right to the diagonal
        row = ty;
        col = (bx - col_blocks + 1) * BLOCK_SIZE + tx;
    }

    __shared__ float s_dia[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float s_peri[BLOCK_SIZE][BLOCK_SIZE];

    // load the diagonal and perimeter sub-matrix
    s_dia[ty][tx] = m[OFFSET(ty + offset, tx + offset, matrix_dim)];
    s_peri[ty][tx] = m[OFFSET(row + offset, col + offset, matrix_dim)];
    __syncthreads();

    for (int k = 0; k < BLOCK_SIZE; k++) {
        // process the column m[offset : matrix_dim][offset + k]
        if (at_col && col == k) {
            s_peri[ty][tx] /= s_dia[k][k];
        }
        __syncthreads();

        // process the submatrix at the column (lower triangular)
        if (at_col && col > k) {
            s_peri[ty][tx] -= s_peri[ty][k] * s_dia[k][tx];
        }

        // process the submatrix at the row (upper triangular)
        if (!at_col && row > k) {
            s_peri[ty][tx] -= s_dia[ty][k] * s_peri[k][tx];
        }
        __syncthreads();
    }

    // write back the perimeter sub-matrix
    m[OFFSET(row + offset, col + offset, matrix_dim)] = s_peri[ty][tx];
}

// block tiling shape = (BM, BN), block size = (BX, BY)
template <int BM, int BN, int BX, int BY>
__global__ void lud_perimeter_v3(float *m, int matrix_dim, int offset,
                                 int col_blocks) {
    int bx = blockIdx.x;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * blockDim.x + tx;

    static_assert(BM == BN, "BM must be equal to BN");
    static_assert(BM % BY == 0, "BM must be divisible by BY");
    static_assert(BN % BX == 0, "BN must be divisible by BX");
    static_assert(BN % 4 == 0, "BN must be divisible by 4");
    static_assert(BM * BN / BX / BY % 4 == 0,
                  "BM * BN must be divisible by 4 * BX * BY");
    constexpr int tm = BM / BY;  // thread tile size at row
    constexpr int tn = BN / BX;  // thread tile size at col

    // each thread read 4 floats (float4) at a time
    int s_row = tid * 4 / BN;
    int s_col = tid * 4 % BN;
    constexpr int s_row_stride = 4 * BX * BY / BN;

    bool at_col = (bx < col_blocks);
    int row_offset = at_col ? (bx + 1) * BM : 0;
    int col_offset = at_col ? 0 : (bx - col_blocks + 1) * BN;
    int row = ty * tm;
    int col = tx * tn;

    __shared__ float s_dia[BM][BN];
    __shared__ float s_peri[BM][BN];

    // load the diagonal and perimeter sub-matrix
    for (int i = s_row; i < BM; i += s_row_stride) {
        FETCH_FLOAT4(s_dia[i][s_col]) =
            FETCH_FLOAT4(m[OFFSET(i + offset, s_col + offset, matrix_dim)]);
        FETCH_FLOAT4(s_peri[i][s_col]) = FETCH_FLOAT4(m[OFFSET(
            i + row_offset + offset, s_col + col_offset + offset, matrix_dim)]);
    }
    __syncthreads();

    // for (int k = 0; k < BLOCK_SIZE; k++) {
    //     // process the column m[offset : matrix_dim][offset + k]
    //     if (at_col && col == k) {
    //         s_peri[ty][tx] /= s_dia[k][k];
    //     }
    //     __syncthreads();

    //     // process the submatrix at the column (lower triangular)
    //     if (at_col && col > k) {
    //         s_peri[ty][tx] -= s_peri[ty][k] * s_dia[k][tx];
    //     }

    //     // process the submatrix at the row (upper triangular)
    //     if (!at_col && row > k) {
    //         s_peri[ty][tx] -= s_dia[ty][k] * s_peri[k][tx];
    //     }
    //     __syncthreads();
    // }

    for (int k = 0; k < BM; k++) {
        // process the column m[offset : matrix_dim][offset + k]
        if (at_col && k >= col && k < col + tn) {
            float diag_k = s_dia[k][k];
            for (int i = row; i < row + tm; i++) {
                s_peri[i][k] /= diag_k;
            }
        }
        __syncthreads();

        // process the submatrix at the column (lower triangular)
        if (at_col && k + 1 < col + tn) {
            for (int i = row; i < row + tm; i++) {
                for (int j = max(col, k + 1); j < col + tn; j++) {
                    s_peri[i][j] -= s_peri[i][k] * s_dia[k][j];
                }
            }
        }

        // process the submatrix at the row (upper triangular)
        if (!at_col && k + 1 < row + tm) {
            for (int i = max(row, k + 1); i < row + tm; i++) {
                for (int j = col; j < col + tn; j++) {
                    s_peri[i][j] -= s_dia[i][k] * s_peri[k][j];
                }
            }
        }
        __syncthreads();
    }

    // write back the perimeter sub-matrix
    for (int i = s_row; i < BM; i += s_row_stride) {
        FETCH_FLOAT4(m[OFFSET(i + row_offset + offset,
                              s_col + col_offset + offset, matrix_dim)]) =
            FETCH_FLOAT4(s_peri[i][s_col]);
    }
}

// fuse the internal kernel with the next diagonal kernel
__global__ void lud_internal_diagonal_fused(float *m, int matrix_dim,
                                            int offset) {
    __shared__ float peri_row[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float peri_col[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float s_m[BLOCK_SIZE][BLOCK_SIZE];

    int i;
    float sum;

    int global_row_id = offset + (blockIdx.y + 1) * BLOCK_SIZE;
    int global_col_id = offset + (blockIdx.x + 1) * BLOCK_SIZE;

    peri_row[threadIdx.y][threadIdx.x] =
        m[(offset + threadIdx.y) * matrix_dim + global_col_id + threadIdx.x];
    peri_col[threadIdx.y][threadIdx.x] =
        m[(global_row_id + threadIdx.y) * matrix_dim + offset + threadIdx.x];

    __syncthreads();

    sum = 0;
    for (i = 0; i < BLOCK_SIZE; i++)
        sum += peri_col[threadIdx.y][i] * peri_row[i][threadIdx.x];

    // process the next diagonal
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = ty;
    int col = tx;

    bool at_diagonal = (blockIdx.x == 0 && blockIdx.y == 0);

    s_m[row][col] =
        m[OFFSET(global_row_id + row, global_col_id + col, matrix_dim)];
    s_m[row][col] -= sum;
    __syncthreads();

    for (int k = 0; k < BLOCK_SIZE; k++) {
        // process the column m[offset : offset + BS][offset + k]
        if (at_diagonal && row > k && col == k) {
            s_m[row][col] /= s_m[k][k];
        }
        __syncthreads();

        // process the sub-matrix m[offset : offset + BS][offset : offset + BS]
        if (at_diagonal && row > k && col > k) {
            s_m[row][col] -= s_m[row][k] * s_m[k][col];
        }
        __syncthreads();
    }

    m[OFFSET(global_row_id + row, global_col_id + col, matrix_dim)] =
        s_m[row][col];
}

// lud_cuda wrapper
void lud_cuda_wrapper(float *m, float *d_m, int matrix_dim,
                      float *kernel_time) {
    checkCudaStatus(cudaMemcpy(d_m, m, matrix_dim * matrix_dim * sizeof(float),
                               cudaMemcpyHostToDevice),
                    "Failed to copy matrix to device");
    // sync cudaMemcpy
    checkCudaStatus(cudaDeviceSynchronize(), "Failed to synchronize device");

    stopwatch timer;
    stopwatch_start(&timer);
    nvtxRangePush("lud_rodiana");
    lud_cuda(d_m, matrix_dim);
    checkCudaStatus(cudaGetLastError(), "Failed to launch kernel");
    checkCudaStatus(cudaDeviceSynchronize(), "Failed to synchronize device");
    nvtxRangePop();
    stopwatch_stop(&timer);
    *kernel_time = get_interval_by_sec(&timer) * 1000;

    checkCudaStatus(cudaMemcpy(m, d_m, matrix_dim * matrix_dim * sizeof(float),
                               cudaMemcpyDeviceToHost),
                    "Failed to copy matrix back to host");
}

// cublas getrf wrapper
void lud_cublas_wrapper(float *m, float *d_m, int matrix_dim,
                        float *kernel_time) {
    // cublasSgetrfBatched requires the matrix to be stored in column-major
    // order so we need to transpose the matrix
    float *m_col_major =
        (float *)malloc(matrix_dim * matrix_dim * sizeof(float));
    for (int i = 0; i < matrix_dim; i++) {
        for (int j = 0; j < matrix_dim; j++) {
            m_col_major[j * matrix_dim + i] = m[i * matrix_dim + j];
        }
    }

    cublasHandle_t handle;
    checkCublasStatus(cublasCreate(&handle), "Failed to create cuBLAS handle");

    int *d_info;
    checkCudaStatus(cudaMalloc((void **)&d_info, sizeof(int)),
                    "Failed to allocate device memory for info");

    // Create array of pointers for batched operation
    float **d_Marray;
    checkCudaStatus(cudaMalloc((void **)&d_Marray, sizeof(float *)),
                    "Failed to allocate device memory for d_Marray");
    checkCudaStatus(
        cudaMemcpy(d_Marray, &d_m, sizeof(float *), cudaMemcpyHostToDevice),
        "Failed to copy d_A to d_Marray");

    checkCudaStatus(
        cudaMemcpy(d_m, m_col_major, matrix_dim * matrix_dim * sizeof(float),
                   cudaMemcpyHostToDevice),
        "Failed to copy matrix to device");
    // sync cudaMemcpy
    checkCudaStatus(cudaDeviceSynchronize(), "Failed to synchronize device");

    stopwatch timer;
    stopwatch_start(&timer);
    nvtxRangePush("lud_cublas");
    checkCublasStatus(cublasSgetrfBatched(handle, matrix_dim, d_Marray,
                                          matrix_dim, NULL, d_info, 1),
                      "Failed to perform LU decomposition");
    checkCudaStatus(cudaGetLastError(), "Failed to launch kernel");
    checkCudaStatus(cudaDeviceSynchronize(), "Failed to synchronize device");
    nvtxRangePop();
    stopwatch_stop(&timer);
    *kernel_time = get_interval_by_sec(&timer) * 1000;

    checkCudaStatus(
        cudaMemcpy(m_col_major, d_m, matrix_dim * matrix_dim * sizeof(float),
                   cudaMemcpyDeviceToHost),
        "Failed to copy matrix back to host");

    // transpose the matrix back
    for (int i = 0; i < matrix_dim; i++) {
        for (int j = 0; j < matrix_dim; j++) {
            m[i * matrix_dim + j] = m_col_major[j * matrix_dim + i];
        }
    }
}

// my lud wrapper
void lud_v2_wrapper(float *m, float *d_m, int matrix_dim, float *kernel_time) {
    checkCudaStatus(cudaMemcpy(d_m, m, matrix_dim * matrix_dim * sizeof(float),
                               cudaMemcpyHostToDevice),
                    "Failed to copy matrix to device");
    // sync cudaMemcpy
    checkCudaStatus(cudaDeviceSynchronize(), "Failed to synchronize device");

    stopwatch timer;
    stopwatch_start(&timer);
    nvtxRangePush("lud_v2");

    int i = 0;
    dim3 dimBlock(BLOCK_SIZE, BLOCK_SIZE);

    for (i = 0; i < matrix_dim - BLOCK_SIZE; i += BLOCK_SIZE) {
        // process the diagonal m[i : i+BLOCK_SIZE][i : i+BLOCK_SIZE]
        lud_diagonal_v2<<<1, dimBlock>>>(d_m, matrix_dim, i);

        // process m[i+BLOCK_SIZE : matrix_dim][i : i+BLOCK_SIZE] and
        // m[i : i+BLOCK_SIZE][i+BLOCK_SIZE : matrix_dim]
        lud_perimeter_v2<<<((matrix_dim - i) / BLOCK_SIZE - 1) * 2, dimBlock>>>(
            d_m, matrix_dim, i, (matrix_dim - i) / BLOCK_SIZE - 1);

        // process m[i+BLOCK_SIZE : matrix_dim][i+BLOCK_SIZE : matrix_dim]
        dim3 dimGrid((matrix_dim - i) / BLOCK_SIZE - 1,
                     (matrix_dim - i) / BLOCK_SIZE - 1);
        lud_internal<<<dimGrid, dimBlock>>>(d_m, matrix_dim, i);
    }

    // process the last diagonal block
    lud_diagonal_v2<<<1, dimBlock>>>(d_m, matrix_dim, i);

    checkCudaStatus(cudaGetLastError(), "Failed to launch kernel");
    checkCudaStatus(cudaDeviceSynchronize(), "Failed to synchronize device");

    nvtxRangePop();
    stopwatch_stop(&timer);
    *kernel_time = get_interval_by_sec(&timer) * 1000;

    checkCudaStatus(cudaMemcpy(m, d_m, matrix_dim * matrix_dim * sizeof(float),
                               cudaMemcpyDeviceToHost),
                    "Failed to copy matrix back to host");
}

