// get catalog filters
function get_filters() {
  $fields = [];

  $property = new WP_Query([
    'post_type' => 'property',
    'posts_per_page' => -1,
  ]);

  while( $property->have_posts() ) {
    $property->the_post();
    $acf = get_fields();

    $fields['type'][] = $acf['type'] ?? '';
    $fields['category'][] = $acf['category'] ?? '';
    $fields['object'][] = $acf['object'] ?? '';
    $fields['status'][] = $acf['status'] ?? '';
    $fields['price'][] = $acf['price'] ?? '';
    $fields['city'][] = $acf['city'] ?? '';
  }

  // clean data
  foreach ($fields as $key => $field) {
    $fields[ $key ] = $key !== 'price' ? cleanArray( $field ) : $field;
  }

  // clean prices
  $fields['price'] = cleanPrices( $fields['price'] );

  wp_reset_postdata();
  return $fields;
}

function cleanArray($data) {
  // filter out empty elements
  $filtered = array_filter($data, function($item) {
      return is_array($item) && !empty($item);
  });

  // remove duplicates
  $unique = array_unique(array_map('serialize', $filtered));
  return array_map('unserialize', $unique);
}

function cleanPrices( $prices ) {
  $output = [];

  // Remove empty elements from the array
  $cleanedPrices = array_filter($prices, function($value) {
    return ($value !== '' && $value !== NULL);
  });

  // Calculate minimum and maximum values
  $output['min'] = number_format( min($cleanedPrices), 0, '.', ' ' );
  $output['max'] = number_format( max($cleanedPrices), 0, '.', ' ' );

  return $output;
}



