  const getRectangleProps = (progression: number, x: number, y: number) => {
    const xOffset = progression == 0 ? 10 : 30 * x + 10;
    const yOffset = progression == 0 ? 10 : 30 * y + 10;
    let fill = "none";
    if (progression >= 2) {
      if (y == 0) {
        fill = "rgb(255 40 10)";
      }
      if (y == 1 && [0, 2, 3].includes(x)) {
        fill = "rgb(255 40 10)";
      }
    }
    if (progression >= 3) {
      if ((y == 1 && x == 1) || (y == 2 && [0, 2, 3].includes(x))) {
        fill = "rgb(10 255 40)";
      }
      if ((y == 2 && x == 1) || (y == 3 && [0, 2].includes(x))) {
        fill = "rgb(10 255 40)";
      }
    }
    if (progression >= 4) {
      if (y == 3 && [1, 3].includes(x)) {
        fill = "rgb(10 40 255)";
      }
      if (y == 4) {
        fill = "rgb(10 40 255)";
      }
      if (y == 5 && x == 0) {
        fill = "rgb(10 40 255)";
      }
    }
    if (progression >= 5) {
      if (y < 5 || (y == 5 && x == 0)) {
        const index = y * 4 + x;
        fill = `hsl(${hues[index]}, 100%, 50%)`;
      }
    }
    if (progression >= 6) {
      if (y > 5 || (y == 5 && x > 0)) {
        fill = `hsl(${50 + x * 10 + (y > 5 ? 10 : 0)}, 100%, 50%)`;
      }
    }
    const stroke = fill == "none" ? "rgb(var(--m3-scheme-primary))" : "none";
    return { x: xOffset, y: yOffset, fill, stroke };
  };
