    def _extract_signer_section(self, cells: List[BeautifulSoup], elements: Dict, is_continuation: bool = False) -> None:
        """Extract signer information from table cells"""
        if is_continuation:
            if len(cells) == 3:
                org_link = cells[0].find('a')
                if org_link:
                    org_name = org_link.get_text(strip=True).split(';#')[0]
