                        'organization': org_name
                    })

    def _extract_scope_section(self, cells: List[BeautifulSoup], elements: Dict) -> None:
        """Extract scope information from table cells"""
        if len(cells) > 1:
            if ul_element := cells[1].find('ul'):
                elements['scopes'] = [li.get_text(strip=True) for li in ul_element.find_all('li') if
                                      li.get_text(strip=True)]
            else:
                scope_value = cells[1].get_text(strip=True)
                if scope_value:
                    elements['scopes'].append(scope_value)

    def _extract_field_section(self, cells: List[BeautifulSoup], elements: Dict, field_mapping: Dict) -> None:
        """Extract field information from table cells"""
        if len(cells) in [2, 4]:
            for i in range(0, len(cells), 2):
                if i + 1 >= len(cells):
                    break

                label = cells[i].get_text(strip=True)
                value_cell = cells[i + 1]

                link = None
                ul_element = None

                if label == 'Loại văn bản':
                    link = value_cell.find('a')
                    if link:
                        elements['type'] = link.get_text(strip=True)
                    continue

                ul_element = value_cell.find('ul')
                if ul_element:
                    values = [li.get_text(strip=True) for li in ul_element.find_all('li') if
                              li.get_text(strip=True)]
                    if label == 'Ngành':
                        elements['fields'] = values
                    elif label == 'Lĩnh vực':
                        elements['subjects'] = values
                    elif label == 'Phạm vi':
                        elements['scopes'] = values
                elif field_name := field_mapping.get(label):
                    elements[field_name] = value_cell.get_text(strip=True)

    def _clean_up_empty_lists(self, elements: Dict) -> None:
        """Clean up empty lists in elements"""
        for key in ['issuing_bodies', 'signers', 'fields', 'subjects', 'scopes']:
            if not elements[key]:
                del elements[key]

    def _extract_elements(self, soup: BeautifulSoup) -> Dict[str, Any]:
        """Extract properties data from .vbProperties table"""
        elements = {
            'title': '',
            'issuing_bodies': [],
            'signers': [],
            'fields': [],
            'subjects': [],
            'scopes': []
        }

        if not (properties_table := soup.select_one('.vbProperties table')):
            return elements

        field_mapping = {
            'Tiêu đề': 'title',
            'Số ký hiệu': 'code',
            'Loại văn bản': 'type',
            'Nguồn thu thập': 'source',
            'Ngành': 'field',
            'Lĩnh vực': 'subject',
            'Ngày ban hành': 'issued_date',
            'Ngày có hiệu lực': 'effective_date',
            'Ngày đăng công báo': 'gazette_date',
            'Phạm vi': 'scope',
            'Tình trạng hiệu lực': 'status'
        }

        elements['title'] = self._extract_title(properties_table)
        rows = self._extract_table_rows(properties_table)
        is_signer_section = False

        for row in rows:
            cells = row.find_all('td')
            if not cells:
                continue

            first_cell_text = cells[0].get_text(strip=True)

            if 'Cơ quan ban hành' in first_cell_text and 'Người ký' in first_cell_text:
                is_signer_section = True
                self._extract_signer_section(cells, elements)
