            if first_cell_text == 'Phạm vi':
                is_signer_section = False
                self._extract_scope_section(cells, elements)
                continue

            if is_signer_section:
                self._extract_signer_section(cells, elements, is_continuation=True)
            else:
                self._extract_field_section(cells, elements, field_mapping)

        self._clean_up_empty_lists(elements)
        return elements

    def _create_history_event(self, cells: List) -> Dict:
        """Create a history event dictionary from table cells."""
        history_event = {
            'date': cells[0].get_text(strip=True),
            'status': cells[1].get_text(strip=True),
            'source_document': None,
            'source_url': None,
            'affected_parts': None
        }
        self._extract_source_info(cells, history_event)
        if len(cells) > 3:
            affected_parts = cells[3].get_text(strip=True)
            if affected_parts:
                history_event['affected_parts'] = affected_parts
        return {k: v for k, v in history_event.items() if v is not None}

    def _extract_source_info(self, cells: List, history_event: Dict):
        """Extract source document information from table cells."""
        source_cell = cells[2]
        if source_link := source_cell.find('a'):
            history_event['source_document'] = source_link.get_text(strip=True)
            history_event['source_url'] = source_link.get('href')
        else:
            history_event['source_document'] = source_cell.get_text(strip=True)

    def _extract_history(self, soup: BeautifulSoup) -> List[Dict]:
        """Extract dữ liệu lịch sử văn bản"""
        history_data = []
        history_table = soup.find('table', {'cellspacing': '1px'})
        if not history_table:
            return history_data

        rows = history_table.find_all('tr')[2:]
        for row in rows:
            cells = row.find_all('td')
            if len(cells) < 3:
                continue
            history_event = self._create_history_event(cells)
            history_data.append(history_event)
        return history_data

    def _extract_related_document_info(self, doc_block: BeautifulSoup) -> Optional[Dict]:
        """Extract information for a single related document."""
        title_div = doc_block.find('div', class_='title')
        if not title_div:
            return None

        relationship_type = ''
        for link in title_div.find_all('a'):
            if not link.get('class') or 'openClose' not in link.get('class'):
                relationship_type = link.get_text(strip=True)
                break

        content_div = doc_block.find('div', class_='content')
        if not content_div:
            return None

        for doc_item in content_div.find_all('li'):
            main_link = doc_item.find('a', class_='jTips')
            if not main_link:
                continue

            doc_data = {
                'relationship_type': relationship_type,
                'title': main_link.get('title', '').strip() or main_link.get_text(strip=True),
                'url_relationship': main_link.get('href', ''),
                'url': '',
                'status': ''
            }

            if status_span := main_link.find('span'):
                doc_data['status'] = status_span.get_text(strip=True).strip('()')

            if links_p := doc_item.find('p'):
                for link in links_p.find_all('a'):
                    if '[Toàn văn]' in link.get_text():
                        doc_data['url'] = link.get('href', '')
                        break

            if doc_data['relationship_type'] and doc_data['title'] and doc_data['url'] and doc_data[
                'url_relationship']:
                return doc_data
        return None

    def _extract_related_documents(self, soup: BeautifulSoup) -> List[Dict]:
        """Extract dữ liệu văn bản liên quan từ bảng lược đồ"""
        related_docs = []
        luocdo_container = soup.find('div', class_='vbLuocDo')
        if not luocdo_container:
            return related_docs

        for doc_block in luocdo_container.find_all('div', class_='luocdo'):
            if doc_block.find('div', class_='titleht'):
                continue
            related_doc = self._extract_related_document_info(doc_block)
            if related_doc:
                related_docs.append(related_doc)
        return related_docs

    @retry(max_retries=10, base_delay=5, max_delay=60)
    async def fetch_page_data(self, url: str) -> Optional[str]:
        if cached_content := self._get_from_cache(url):
            return cached_content

        try:
            async with self.session.get(
                url,
                allow_redirects=True,
                timeout=aiohttp.ClientTimeout(
                    total=60,
                    connect=20,
                    sock_read=40
                )
            ) as response:
                if response.status != 200:
                    logger.warning(f"Non-200 status code ({response.status}) for URL: {url}")
                    return None

                try:
                    text = await asyncio.wait_for(
                        response.text(),
                        timeout=30  # Timeout riêng cho việc đọc response
                    )
                    self._add_to_cache(url, text)
                    return text
                except asyncio.TimeoutError:
                    logger.warning(f"Timeout reading response for URL: {url}")
                    raise

        except (aiohttp.ClientError, asyncio.TimeoutError) as e:
            logger.warning(f"Error fetching {url}: {str(e)}")
            raise
        except Exception as e:
            logger.error(f"Unexpected error fetching {url}: {str(e)}")
            raise

    async def process_document(self, document: Dict[str, str]) -> bool:
        try:
            validated_document = await self._validate_document(document)
            if not validated_document:
                return False

            related_data = await self._fetch_related_data(validated_document['url'])
            if not related_data:
                return False

            if await self._check_duplicate_document(validated_document['url'], related_data['elements']):
                return False

            document_metadata = await self._extract_document_content(validated_document['url'], validated_document['title'], related_data, document)

            if document_metadata.get("status") == "pending_content":
                code = document_metadata.get("elements", {}).get("code")
                if code:
                    new_content = await self._fetch_document_by_code(code)
                    document_metadata["full_text"] = new_content
                    document_metadata["status"] = "success"

            await self._save_document_data(document, document_metadata)

            return document_metadata.get("status") == "success"

        except Exception as e:
            error_msg = f"Lỗi không xác định: {str(e)}"
            logger.error(f"Lỗi khi xử lý {document.get('title')}: {error_msg}")
            document['reason'] = error_msg
            await self.file_handler.save_invalid_url(document)
            await self.file_handler.save_document_metadata(document_metadata)
            return False

    async def _validate_document(self, document: Dict[str, str]) -> Optional[Dict[str, str]]:
        if not isinstance(document, dict):
            logger.error("Invalid document format - expected dictionary")
            return None

        url = document.get('url')
        if not url:
            logger.error("Document missing required 'url' field")
            await self.file_handler.save_invalid_url({
                **document,
                'reason': 'Missing URL field'
            })
            return None

        return document

    async def _fetch_related_data(self, url: str) -> Optional[Dict]:
        item_id = url.split('ItemID=')[-1]
        related_urls = await self.get_related_urls(item_id)
        tasks = [
            self.fetch_page_data(related_url)
            for related_url in related_urls.values()
        ]
        html_contents = await asyncio.gather(*tasks)

        additional_data = {}
        has_metadata = False
        for page_type, html_content in zip(related_urls.keys(), html_contents):
            if html_content:
                page_data = await self.extract_page_data(html_content, page_type)
                if page_data:
                    has_metadata = True
                    additional_data[page_type] = page_data
        return {
            "elements": additional_data.get('elements', {}),
            "history": additional_data.get('history', []),
            "related_documents": additional_data.get('related_documents', []),
            "has_metadata": has_metadata,
        }

    async def _check_duplicate_document(self, url: str, current_elements: Dict) -> bool:
        if not current_elements:
            return False

        collection_file = self.file_handler.output_dir / 'vbpl_document_chitiet.json'
        existing_data = self.file_handler._load_json_file(collection_file)
        if not existing_data or 'documents' not in existing_data:
            return False

        current_elements_hash = hash(json.dumps(current_elements, sort_keys=True))
        existing_hashes = {
            hash(json.dumps(doc.get('elements', {}), sort_keys=True))
            for doc in existing_data['documents'] if 'elements' in doc
        }
        if current_elements_hash in existing_hashes and bool(current_elements):
            logger.info(f"Duplicate document found based on elements: {url}")
            return True
        return False

    async def _extract_document_content(self, url: str, title: str, related_data: Dict, document: Dict) -> Dict:
        document_metadata = {
            "elements": related_data.get('elements', {}),
            "history": related_data.get('history', []),
            "related_documents": related_data.get('related_documents', []),
            "full_text": "",
            "metadata": document,
            "status": "pending_content",
        }
        if  related_data and isinstance(related_data.get('related_documents'), list):
            document_metadata["related_documents"] = related_data.get('related_documents', [])

        has_metadata = related_data.get('has_metadata', False)
        valid_url_format = 'vbpl.vn/TW/Pages/vbpq-toanvan.aspx?ItemID=' in url
        full_text = None
        metadata = None
        if valid_url_format:
            for attempt in range(self.max_retries):
                try:
                    if main_content := await self.fetch_page_data(url):
                        soup = BeautifulSoup(main_content, 'html.parser')
                        metadata = self.extractor.extract_metadata(soup)
                        if metadata:
                            has_metadata = True
                        full_text = self.extractor.extract_full_text(soup)
                        if full_text:
                            break

                    error_msg = "Không tìm thấy nội dung toàn văn"
                    logger.warning(
                        f"{error_msg}: {title} "
                        f"(lần thử {attempt + 1}/{self.max_retries})"
                    )
                    if attempt < self.max_retries - 1:
                        await asyncio.sleep(1)
                        continue
                    document_metadata['reason'] = error_msg

                except (aiohttp.ClientError, asyncio.TimeoutError, json.JSONDecodeError) as e:
                    error_msg = await self._handle_fetch_error(e, title, url, attempt)
                    if error_msg:
                        document_metadata['reason'] = error_msg
                except Exception as e:
                    error_msg = f"Lỗi không xác định: {str(e)}"
                    logger.error(
                        f"{error_msg} khi xử lý {title} "
                        f"(lần thử {attempt + 1}/{self.max_retries}) - URL: {url}"
                    )
                    if attempt < self.max_retries - 1:
                        await asyncio.sleep(5)
                        continue
                    document_metadata['reason'] = error_msg
        else:
            logger.info(f"URL không đúng định dạng toàn văn: {title}")
            code = document_metadata.get("elements", {}).get("code")
            if code:
                new_content = await self._fetch_document_by_code(code)
                if new_content:
                    document_metadata["full_text"] = new_content
                    document_metadata["status"] = "success"
                else:
                    document_metadata['reason'] = "URL không đúng định dạng toàn văn và không lấy được nội dung từ code"
            else:
                document_metadata['reason'] = "URL không đúng định dạng toàn văn"

        document_metadata.update({
            "full_text": full_text or "",
        })
        if metadata:
            document_metadata["metadata"].update(metadata)
        if full_text:
            document_metadata["status"] = "success"

        if not has_metadata:
            document_metadata['attempts'] = self.max_retries
            document_metadata['reason'] = "Không lấy được metadata và các thuộc tính"

        return document_metadata

    async def _save_document_data(self, document: Dict, document_metadata: Dict) -> None:
        if document_metadata.get('reason'):
            document['attempts'] = self.max_retries
            document['reason'] = document_metadata['reason']
            await self.file_handler.save_invalid_url(document)
            logger.error(
                f"Không lấy được metadata cho {document.get('title')}: "
                f"{document.get('reason', 'Không có lỗi cụ thể')}"
            )

        document_metadata["metadata"] = document
        await self.file_handler.save_document_metadata(document_metadata)

    async def _handle_fetch_error(self, e: Exception, title: str, url: str, attempt: int) -> Optional[str]:
        """Handle fetch errors and log them."""
        error_msg = None
        if isinstance(e, aiohttp.ClientError):
            error_msg = f"Lỗi HTTP: {str(e)}"
            logger.error(
                f"{error_msg} khi xử lý {title} "
                f"(lần thử {attempt + 1}/{self.max_retries}) - URL: {url}"
            )
            if attempt < self.max_retries - 1:
                await asyncio.sleep(15)
        elif isinstance(e, asyncio.TimeoutError):
            error_msg = f"Lỗi Timeout: {str(e)}"
            logger.error(
                f"{error_msg} khi xử lý {title} "
                f"(lần thử {attempt + 1}/{self.max_retries}) - URL: {url}"
            )
            if attempt < self.max_retries - 1:
                await asyncio.sleep(5)
        elif isinstance(e, json.JSONDecodeError):
            error_msg = f"Lỗi JSON: {str(e)}"
            logger.error(
                f"{error_msg} khi xử lý {title} "
                f"(lần thử {attempt + 1}/{self.max_retries}) - URL: {url}"
            )
            if attempt < self.max_retries - 1:
                await asyncio.sleep(5)
        return error_msg

    async def process_documents(self) -> None:
        """Process all documents với batch processing và concurrent control"""
        try:
            data = self._load_documents()
            if not data:
                return

            documents = data.get('documents', [])

            # Khởi tạo semaphore
            self.semaphore = asyncio.Semaphore(self.max_concurrent)

            # Tối ưu connector settings
            connector = aiohttp.TCPConnector(
                limit=self.max_concurrent, # Giới hạn số lượng kết nối đồng thời
                ttl_dns_cache=600, # Thời gian cache DNS (giây)
                use_dns_cache=True, # Sử dụng cache DNS
                force_close=False,
                enable_cleanup_closed=True, # Cho phép dọn dẹp các kết nối đã đóng
                keepalive_timeout=120, # Thời gian giữ kết nối (giây)
            )

            # Tăng timeout tổng thể
            timeout = aiohttp.ClientTimeout(
                total=120,  # 2 phút cho toàn bộ request
                connect=20,
                sock_read=40,
                sock_connect=20
            )


            async with aiohttp.ClientSession(
                    connector=connector,
                    timeout=timeout,
                    trust_env=True,
                    headers={
                        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
                        'Accept-Language': 'en-US,en;q=0.5',
                        'Connection': 'keep-alive',
                    }
            ) as session:
                self.session = session

                # Process theo batch với semaphore
                for i in range(0, len(documents), self.batch_size):
                    batch = documents[i:i + self.batch_size]
                    start_time = datetime.now()
                    self._start_time = start_time
                    logger.info(f"Start processing batch {i // self.batch_size + 1} with {len(batch)} documents")

                    total_documents = len(documents)
                    tasks = []

                    # Tạo tasks với semaphore đã được khởi tạo
                    for doc in batch:
                        task = asyncio.create_task(self._process_with_semaphore(doc, total_documents))
                        tasks.append(task)

                    try:
                        results = await asyncio.gather(*tasks, return_exceptions=True)

                        # Update stats và xử lý kết quả
                        for result in results:
                            if isinstance(result, Exception):
                                self._stats['errors'] += 1
                                logger.error(f"Error processing document: {str(result)}")
                            else:
                                self._stats['processed'] += 1
                                if result:
                                    self._stats['successful'] += 1
                                else:
                                    self._stats['failed'] += 1

                    except Exception as e:
                        logger.error(f"Error processing batch: {str(e)}")
                        self._stats['errors'] += len(batch)

                    end_time = datetime.now()
                    duration = (end_time - start_time).total_seconds()
                    logger.info(f"Finished processing batch {i // self.batch_size + 1} in {duration:.2f} seconds. Processed {len(batch)} documents")

                    # Adaptive concurrency
                    error_rate = self._stats['errors'] / (self._stats['processed'] + 1)
                    if error_rate > 0.2 and self.max_concurrent > 10:
                        self.max_concurrent = max(10, int(self.max_concurrent * 0.8))
                        logger.warning(f"Reducing max_concurrent to {self.max_concurrent} due to high error rate")
                    elif error_rate < 0.05 and self.max_concurrent < self.initial_max_concurrent:
                        self.max_concurrent = min(self.initial_max_concurrent, int(self.max_concurrent * 1.2))
                        logger.info(f"Increasing max_concurrent to {self.max_concurrent} due to low error rate")
                    elif self.max_concurrent < self.initial_max_concurrent:
                        # Increase max_concurrent gradually
                        self.max_concurrent = min(self.initial_max_concurrent, self.max_concurrent + 2)
                        logger.info(f"Increasing max_concurrent to {self.max_concurrent}")

                    # Remove pause

            logger.info(
                f"Processing completed: "
                f"Total={self._stats['processed']}, "
                f"Success={self._stats['successful']}, "
                f"Failed={self._stats['failed']}, "
                f"Errors={self._stats['errors']}, "
                f"Cached={self._stats['cached']}"
            )

        except Exception as e:
            logger.error(f"Lỗi trong quá trình xử lý documents: {str(e)}")
            raise
        finally:
            self._save_cache()

    def _load_documents(self) -> Optional[Dict]:
        """Load documents from JSON file"""
        try:
            with open(self.json_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            logger.error(f"Không tìm thấy file: {self.json_path}")
        except json.JSONDecodeError:
            logger.error(f"File JSON không hợp lệ: {self.json_path}")
        except Exception as e:
            logger.error(f"Lỗi khi đọc file JSON: {str(e)}")
        return None

    async def _fetch_document_by_code(self, code: str) -> Optional[str]:
        """Fetch document content from another page using the code."""
        base_url = "https://thuvienphapluat.vn/page/tim-van-ban.aspx"
        search_url = f"{base_url}?keyword={code}&area=2&type=0&status=0&lan=1&org=0&signer=0&match=False&sort=1&bdate=02/01/1945&edate=02/01/2025"

        try:
            async with self.session.get(search_url, allow_redirects=True) as response:
                if response.status != 200:
                    logger.warning(f"Non-200 status code ({response.status}) for URL: {search_url}")
                    return None

                html_content = await response.text()
                soup = BeautifulSoup(html_content, 'html.parser')

                link_element = soup.select_one('.content-0 .nqTitle a')
                if not link_element:
                    logger.warning(f"Could not find document link for code: {code}")
                    return None


                link_element = soup.select_one('.content-0 .nqTitle a')
                if not link_element:
                    logger.warning(f"Could not find document link for code: {code}")
                    return None

                detail_url = link_element['href']

                try:
                    async with self.session.get(detail_url, allow_redirects=True) as detail_response:
                        if detail_response.status != 200:
                            logger.warning(f"Non-200 status code ({detail_response.status}) for URL: {detail_url}")
                            return None

                        detail_html_content = await detail_response.text()
                        detail_soup = BeautifulSoup(detail_html_content, 'html.parser')

                        content_div = detail_soup.select_one('.content1')
                        if not content_div:
                            logger.warning(f"Could not find content div for code: {code}")
                            return None

                        full_text = self.extractor.converter.convert(str(content_div))

                        return full_text
                except Exception as e:
                    logger.error(f"Error fetching or parsing detail page for code {code}: {e}")
                    return None
            except Exception as e:
                logger.error(f"Error fetching document by code {code}: {e}")
                return None

