{-@ type Rule = (String, [String]) @-}
{-@ type FirstSet = Map String (Set String) @-}

{-@ measure first :: Rule -> Set String @-}
{-@ first (lhs, rhs) = first' rhs @-}

{-@ measure first' :: [String] -> Set String @-}
first' [] = Set.empty
first' (x:xs) =
  if isTerminal x
  then Set.singleton x `Set.union` first' xs
  else Set.union (Set.fromList (fromMaybe [] (Lib.lookup x firstSet))) (first' xs)


{-@ firstSet :: FirstSet @-}
{-@ type Map k v = [(k, v)] @-}
{-@ type Set a = [a] @-}

{-@ isTerminal :: String -> Bool @-}
isTerminal s = s `notElem` productions

{-@ computeFirstSet :: [Rule] -> FirstSet @-}
computeFirstSet productions = go productions mempty
  where
    go [] acc = acc
    go ((lhs, rhs):rules) acc =
      let newFirst = first (lhs, rhs)
          updatedAcc = Map.insertWith Set.union lhs newFirst acc
      in go rules updatedAcc

    {-@ mempty :: FirstSet @-}
    mempty = []

{-@ measure lookup :: String -> FirstSet -> Maybe (Set String) @-}
lookup k m = lookup' k m
  where
    lookup' _ [] = Nothing
    lookup' k ((k',v):xs) = if k == k' then Just v else lookup' k xs

{-@ measure insertWith :: (Set String -> Set String -> Set String) -> String -> Set String -> FirstSet -> FirstSet @-}
insertWith f k v m = (k,v) : m

{-@ measure union :: Set String -> Set String -> Set String @-}
union xs ys = nub (xs ++ ys)

{-@ measure singleton :: String -> Set String @-}
singleton x = [x]


{-@ measure fromList :: [String] -> Set String @-}
fromList = nub


