# T1
# write function to get factorial of a number
def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

# T2
# write function to get fibonatchi of a number
def fibonacci(n):
    if n <= 1:
        return n
    else:
        return fibonacci(n-1) + fibonacci(n-2)

# T3
# write function to get caeser cipher of a string 
def caeser_cipher(text, shift):
    result = ""
    for char in text:
        if char.isalpha():
            shift_base = ord('A') if char.isupper() else ord('a')
            result += chr((ord(char) - shift_base + shift) % 26 + shift_base)
        else:
            result += char
    return result

# T4
# write function to get max product of three
def max_product_of_three(nums):
    nums.sort()
    return max(nums[0] * nums[1] * nums[-1], nums[-1] * nums[-2] * nums[-3])

# T5
# write function to get median of 2 sorted arrays
def median_of_two_sorted_arrays(nums1, nums2):
    merged = sorted(nums1 + nums2)
    mid = len(merged) // 2
    if len(merged) % 2 == 0:
        return (merged[mid - 1] + merged[mid]) / 2
    else:
        return merged[mid]

# T6
# write function to get longest common prefix of a list of strings
def longest_common_prefix(strs):
    if not strs:
        return ""
    shortest = min(strs, key=len)
    for i, ch in enumerate(shortest):
        for other in strs:
            if other[i] != ch:
                return shortest[:i]
    return shortest

# T7
# write function to check if a string is balance
def is_balanced_string(s):
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}
    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)
    return not stack

# T8
# write function to sort an array
def sort_array(nums):
    return sorted(nums)

# T9
# write function to calc the absolute difference between the sums of its diagonal
def diagonal_difference(matrix):
    primary_diagonal = sum(matrix[i][i] for i in range(len(matrix)))
    secondary_diagonal = sum(matrix[i][len(matrix) - 1 - i] for i in range(len(matrix)))
    return abs(primary_diagonal - secondary_diagonal)

# T10
# write function to get the element that would be at the k'th position of the final sorted array of two sorted arrays
def kth_element_of_two_sorted_arrays(nums1, nums2, k):
    merged = sorted(nums1 + nums2)
    return merged[k - 1]

# T11
# write a product cipher function to shuffle the alphabet using modular multiplication
def product_cipher(text, key):
    result = ""
    for char in text:
        if char.isalpha():
            shift_base = ord('A') if char.isupper() else ord('a')
            result += chr((((ord(char) - shift_base) * key) % 26) + shift_base)
        else:
            result += char
    return result

# T12
# write a function for Affine Cipher Encryption
def affine_cipher(text, a, b):
    result = ""
    for char in text:
        if char.isalpha():
            shift_base = ord('A') if char.isupper() else ord('a')
            result += chr(((a * (ord(char) - shift_base) + b) % 26) + shift_base)
        else:
            result += char
    return result

# T13
# write a function to Calc RSA Encryption Modulo
def rsa_encryption_modulo(m, e, n):
    return pow(m, e, n)

# T14
# write a function for binary search algorithm
def binary_search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

# T15
# write a function for bubble sort algorithm
def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

# T16
# write a function for Counting Sort Algorithm
def counting_sort(arr):
    if not arr:
        return arr

    max_val = max(arr)
    count = [0] * (max_val + 1)

    for num in arr:
        count[num] += 1

    sorted_arr = []
    for num, freq in enumerate(count):
        sorted_arr.extend([num] * freq)

    return sorted_arr

# T17
# write a function to find the Kth Largest Element in an Array
def kth_largest_element(nums, k):
    return sorted(nums, reverse=True)[k - 1]

# T18
# write a function to check if palindrome
def is_palindrome(s):
    return s == s[::-1]

