	// deal the cards to the lists from the deck
	public void deal() {
		// if (deck.isEmpty() || deck.size() < 4) {
		// 	return;
        // }

		if(deck.size() >= 4){
			for (int i = 0; i < 4; i++) {
				PlayingCard dealt = deck.remove(deck.size() - 1);
				lists[i].add(dealt);
			}
