	// discard a card from a list to the discard pile
	public void discard(int listNum) {

		// if the list is empty, or listNum out of bounds, end method
		if (listNum < 0 || listNum >= 4 || lists[listNum].isEmpty()) {
			return;
		}

		// get the card to discard from the list
        PlayingCard cardToDiscard = lists[listNum].get(lists[listNum].size() - 1);

		// check if the card can be discarded to a different list
        for (int i = 0; i < 4; i++) {

			//check other lists that are not empty
            if (i != listNum && !lists[i].isEmpty()) {

				// get the top card of the list
                PlayingCard topCard = lists[i].get(lists[i].size() - 1);

				// if the top card is the same suit and less than the card to discard, discard the card to the discard pile
                if (topCard.getSuit() == cardToDiscard.getSuit() && topCard.getRank() < cardToDiscard.getRank()) {
                    discardPile.add(lists[listNum].remove(lists[listNum].size() - 1));

					// increment the player's score
                    playerScore++;

                    return;
                }
            }
        }
	}

	// move a card from a list to another list
    public void move(int listNum) {
        // check if the listNum is valid and the list is not empty
        if (listNum >= 0 && listNum < 4 && !lists[listNum].isEmpty()) {
            // iterate through lists
            for (int i = 0; i < 4; i++) {
                // check if the iterated list is a valid destination (empty and not the source)
                if (i != listNum && lists[i].isEmpty()) {
                    // move the top card from the source list to the destination list
                    lists[i].add(lists[listNum].remove(lists[listNum].size() - 1));
                    return;
                }
            }
        }           
    }

	// reset the game to initial state
	public void startNewGame() {

