        for (int i = 0; i < 4; i++) {

			// add list cards to deck then clear
			for (int j = 0; j < lists[i].size(); j++) {
				deck.add(lists[i].get(j));
			}

			lists[i].clear();
        }

		//move discard to deck and clear
        for (int k = 0; k < discardPile.size(); k++) {
			deck.add(discardPile.get(k));
		}
        discardPile.clear();

        // add all cards if the game just started, and deck is empty
        if (deck.isEmpty()) {
            for (int i = 1; i <= 13; i++) {
                deck.add(new PlayingCard(i, 'C')); // Add Clubs
                deck.add(new PlayingCard(i, 'S')); // Add Spades
                deck.add(new PlayingCard(i, 'H')); // Add Hearts
                deck.add(new PlayingCard(i, 'D')); // Add Diamonds
            }
        }


        // shuffle the deck
        Collections.shuffle(deck);

        // deal the initial cards to start the game
        deal();

	}





