package DBTorrents;
use strict;
use warnings;
use parent 'DBBase';

use Parsley::GEncoder;

our @VALID_COLUMNS = qw(
    id description episode size episode_number show_name regular_name
    link date magnet group_name group_link rtoken assigned_show_name date_added
    gencoder vencode resolution assigned_timestamp season season_number
    display_description network search_id2
);

sub new {
    my ($class, $db_path) = @_;
    my $self = $class->SUPER::new($db_path);
    $self->{valid_columns} = \@VALID_COLUMNS;
    $self->{table_name} = 'torrents';
    $self->create_table;
    return $self;
}

sub create_table {
    my $self = shift;
    my $exists = $self->{db}->db->query("SELECT name FROM sqlite_master WHERE type='table' AND name='torrents'")->array;

    unless ($exists) {
        $self->{db}->db->query(q{
            CREATE TABLE torrents (
                id TEXT PRIMARY KEY,
                description TEXT,
                episode TEXT,
                size TEXT,
                episode_number TEXT,
                show_name TEXT,
                link TEXT,
                date TEXT,
                magnet TEXT,
                group_name TEXT,
                group_link TEXT,
                rtoken TEXT,
                assigned_show_name TEXT,
                date_added INTEGER,
                assigned_timestamp INTEGER,
                season TEXT,
                season_number TEXT
            )
        });
        $self->create_indexes;
    }
}

sub create_indexes {
    my $self = shift;
    $self->{db}->db->query('CREATE INDEX idx_id_magnet ON torrents (id, magnet)');
    $self->{db}->db->query('CREATE INDEX idx_show_name ON torrents (show_name)');
    $self->{db}->db->query('CREATE INDEX idx_group_name ON torrents (group_name)');
}

sub get_not_queued {
    my ($self) = @_;
    my $sql = q{
        SELECT t.*
        FROM torrents t
        WHERE NOT EXISTS (
            SELECT 1 FROM queued_torrents q 
            WHERE (q.show_name = t.assigned_show_name OR (t.id = q.torrent_id AND q.torrent_id != ''))
        )
        AND NOT EXISTS (
            SELECT 1 FROM torrents t2
            WHERE (t2.assigned_timestamp IS NOT NULL AND t2.assigned_timestamp != '')
            AND strftime('%s', 'now') - t2.assigned_timestamp > 24 * 3600 * 100
            AND t2.assigned_show_name = t.assigned_show_name
            AND t2.episode_number = t.episode_number
            AND t2.season_number = t.season_number
        )
        AND NOT EXISTS (
            SELECT 1 FROM blockers b
            WHERE (b.blocker_name = 'show_name' AND b.value = t.assigned_show_name)
            OR (b.blocker_name = 'id' AND b.value = t.id)
            OR (b.blocker_name = 'episode' AND b.value = t.episode)
            OR (b.blocker_name = 'group_name' AND b.value = t.group_name COLLATE NOCASE)
            OR (b.blocker_name = 'words' AND t.assigned_show_name LIKE '%' || b.value || '%')
            OR (b.blocker_name = 'words' AND t.regular_name LIKE '%' || b.value || '%')
            OR (b.blocker_name = 'season' AND b.value = t.season)
        );
    };
    return $self->{db}->db->query($sql)->hashes->to_array;
}

sub get_queued {
    my ($self) = @_;
    my $sql = q{
        SELECT DISTINCT torrents.*
        FROM torrents
        LEFT JOIN queued_torrents q1 ON q1.category = 'episode' AND torrents.episode = q1.processed AND torrents.episode != ''
        LEFT JOIN queued_torrents q2 ON q2.category = 'season' AND torrents.season = q2.processed AND torrents.season != ''
        LEFT JOIN queued_torrents q3 ON torrents.id = q3.torrent_id
        WHERE q1.n IS NOT NULL 
            OR q2.n IS NOT NULL 
            OR q3.torrent_id IS NOT NULL
    };
    return $self->{db}->db->query($sql)->hashes->to_array;
}

sub get_interests {
    my ($self) = @_;
    my $sql = q{
        SELECT DISTINCT t.*
        FROM torrents t
        WHERE EXISTS (SELECT 1 FROM queued_torrents q WHERE q.show_name = t.assigned_show_name)
        AND NOT EXISTS (SELECT 1 FROM queued_torrents q WHERE t.id = q.torrent_id)
        AND NOT EXISTS (SELECT 1 FROM queued_torrents q 
            WHERE q.category = 'episode' AND t.episode = q.processed AND t.episode != '')
        AND NOT EXISTS (SELECT 1 FROM queued_torrents q
            WHERE q.category = 'season' AND t.season = q.processed AND t.season != '')
        AND NOT EXISTS (SELECT 1 FROM blockers b 
            WHERE b.blocker_name IN ('show_name', 'id', 'episode', 'group_name', 'season')
            AND b.value IN (t.assigned_show_name, t.id, t.episode, t.group_name, t.season))
        AND NOT EXISTS (SELECT 1 FROM blockers b
            WHERE b.blocker_name = 'words' AND t.assigned_show_name LIKE '%' || b.value || '%')
        AND NOT EXISTS (SELECT 1 FROM blockers b
            WHERE b.blocker_name = 'words' AND t.regular_name LIKE '%' || b.value || '%')
    };
    return $self->{db}->db->query($sql)->hashes->to_array;
}

sub with_show_name_sth {
    my ($self, $show_name) = @_;
    return $self->{db}->db->query(q{
        SELECT t.*,
            EXISTS (
                SELECT 1 FROM queued_torrents q 
                WHERE q.torrent_id = t.id
            ) as downloaded,
            CASE 
                WHEN t.season != '' AND EXISTS (
                    SELECT 1 FROM queued_torrents q 
                    WHERE q.category = 'season' AND q.processed = t.season
                ) THEN 1
                WHEN t.episode != '' AND EXISTS (
                    SELECT 1 FROM queued_torrents q 
                    WHERE q.category = 'episode' AND q.processed = t.episode
                ) THEN 1
                ELSE 0 
            END as marked
        FROM torrents t
        WHERE t.assigned_show_name = ?
        ORDER BY season_number ASC, 
            episode_number ASC, 
            CASE WHEN vencode = '' THEN 1 ELSE 0 END ASC,
            vencode ASC, 
            resolution DESC, 
            CAST(size AS INTEGER) ASC
    }, $show_name);
}

sub clear_all {
    my ($self) = @_;
    return $self->{db}->db->query('DELETE FROM torrents');
}

sub insert_one {
    my ($self, $params) = @_;

    return 0 if $self->with_id($params->{id});

    my $filtered_params = $self->filter_params($params);
    $filtered_params->{date_added} = time() if !defined $filtered_params->{date_added};

    $self->{db}->db->insert($self->{table_name}, $filtered_params);
    return 1;
}

# todo find out how to convert today and yesterday to epoch
sub dates_sth {
    my ($self) = @_;
    return $self->{db}->db->query(q{
        SELECT DISTINCT t1.date_added, t2.id, t2.description, t2.date, t2.date_added, t2.assigned_timestamp
        FROM torrents t1
        JOIN torrents t2 ON t1.date_added = t2.date_added
        WHERE t1.date_added > 1729382400
            AND (t1.assigned_timestamp IS NULL OR t1.assigned_timestamp = '')
        ORDER BY t1.date_added ASC, t2.id ASC
    });
}

sub purge_blockers {
    my ($self) = @_;

    # blocked shows
    $self->{db}->db->query(q{
        WITH blocked_shows AS (
            SELECT value 
            FROM blockers 
            WHERE blocker_name = 'show_name'
        ),
        queued_show_names AS (
            SELECT DISTINCT show_name 
            FROM queued_torrents 
            WHERE show_name IS NOT NULL AND show_name != ''
        ),
        queued_torrent_ids AS (
            SELECT DISTINCT torrent_id 
            FROM queued_torrents
            WHERE torrent_id IS NOT NULL AND torrent_id != ''
        )
        DELETE FROM torrents
        WHERE (
            show_name IN (SELECT value FROM blocked_shows)
            OR assigned_show_name IN (SELECT value FROM blocked_shows)
        )
        AND show_name NOT IN (SELECT show_name FROM queued_show_names)
        AND assigned_show_name NOT IN (SELECT show_name FROM queued_show_names)
        AND id NOT IN (SELECT torrent_id FROM queued_torrent_ids);
    });

