def webparser(html:str,id:str):
    links = []
    os.mkdir(os.path.join('images',id))
    base_path = os.path.join('images',id)
    soup = BeautifulSoup(html, 'html.parser')
    title = soup.find('title').text
    grid = soup.find('div', attrs={'class': 'grid'})
    items = grid.find_all('div', attrs={'class': 'grid-item'})
    for item in items:
        layer_a = item.find('a')
        if layer_a is None:
            continue
        if layer_a['href'] in links:
            continue
        if "https://cosplayrule34.com" not in layer_a['href']:
            continue
        links.append(layer_a['href'])
        threading.Thread(target=download_img, args=(layer_a['href'],base_path)).start()
    return title,links

def test_url(url:str,id:str):
    resp = requests.get(url)
    if resp.status_code != 200:
        return False
    webparser(resp.text,str(id))

