import java.io.File;
import java.io.IOException;
import java.nio.file.StandardCopyOption;

import com.szst.database.conversion.ES2ToILCDConversion;
import com.szst.database.util.FolderUtil;

public class SingleConverter {

    public static void copyFilesRecursively(Path sourceDir, Path targetDir) throws IOException {
        if (!Files.exists(targetDir)) {
            Files.createDirectories(targetDir);
        }

        // 遍历源文件夹及其子文件夹
        Files.walk(sourceDir).forEach(sourcePath -> {
            try {
                Path targetPath = targetDir.resolve(sourceDir.relativize(sourcePath));

                if (Files.isDirectory(sourcePath)) {
                    // 如果是目录，确保目标目录存在
                    Files.createDirectories(targetPath);
                } else if (Files.isRegularFile(sourcePath)) {
                    // 如果是文件，复制文件
                    if (Files.exists(targetPath)) {
                        System.out.println("Skipping: " + sourcePath.getFileName() + " (already exists)");
                    } else {
                        Files.copy(sourcePath, targetPath, StandardCopyOption.REPLACE_EXISTING);
                        System.out.println("Copied: " + sourcePath.getFileName());
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        });
    }

    public static void main(String[] args) {

        String spoldPath = "E:/#File/ecoinvent/Allocation cut-off by classification/";

        String ILCDPath = System.getProperty("user.dir") + "/szst-database/src/main/resources/ILCD/";
        String tempPath = System.getProperty("user.dir") + "/szst-database/src/main/resources/temp/";

        // Clean temp folder if exists or create it
        File tempDir = new File(tempPath);
        if(tempDir.exists()){
            FolderUtil.empty(tempDir);
        } else{
            tempDir.mkdirs();
        } 
        File ILCDDir = new File(ILCDPath);
        if(ILCDDir.exists()){
            FolderUtil.empty(ILCDDir);
        } else{
            ILCDDir.mkdirs();
        } 

        // Read files
        File folder = new File(spoldPath);
        if (folder.exists() && folder.isDirectory()) {
            File[] files = folder.listFiles();
            if (files != null) {
                for (File file : files) {
                    if (file.isFile()) {
                        ES2ToILCDConversion conversion = new ES2ToILCDConversion();
                        conversion.setSourceFile(file);
                        conversion.setTargetDir(tempDir);
                        conversion.run();


                        // Clean temp folder
                        FolderUtil.empty(tempDir);
                    }
                }
            }
        }


    }
}

