      .card {
        position: relative;
        width: 300px;
        height: 400px;
        border-radius: 22px;
        display: flex;
        justify-content: center;
        align-items: center;
        overflow: hidden;
        transition: transform 0.3s ease;
      }

      .card:hover {
        transform: translateY(-5px);
      }

      .wave-container {
        position: absolute;
        inset: 0;
        opacity: 0;
        transition: opacity 0.3s;
      }

      .card:hover .wave-container {
        opacity: 1;
      }

      canvas {
        position: absolute;
        top: 0;
        left: 0;
      }

      .card-content {
        position: relative;
        z-index: -1;
        padding: 20px;
      }
    </style>
  </head>
  <body>
    <div class="card">
      <div class="wave-container">
        <canvas id="waveCanvas"></canvas>
      </div>
      <div class="card-content">
        <img src="background.png" alt="" />
        <h2>Hover Me</h2>
      </div>
    </div>

    <script>
      const canvas = document.getElementById("waveCanvas");
      const ctx = canvas.getContext("2d");
      const card = document.querySelector(".card");

      function resizeCanvas() {
        canvas.width = card.offsetWidth;
        canvas.height = card.offsetHeight;
      }

      resizeCanvas();

      let animationFrameId;
      let time = 0;
      let isAnimating = false;

      // Edge wave configurations with different shades of blue
      const waves = [
        {
          color: "rgba(64, 196, 255, 0.8)", // Bright blue
          amplitude: 3,
          frequency: 0.03,
          speed: 1,
          width: 2,
        },
        {
          color: "rgba(30, 144, 255, 0.6)", // Dodger blue
          amplitude: 4,
          frequency: 0.02,
          speed: 0.7,
          width: 2,
        },
        {
          color: "rgba(0, 102, 255, 0.4)", // Royal blue
          amplitude: 5,
          frequency: 0.025,
          speed: 0.5,
          width: 2,
        },
      ];

      function drawEdgeWave(wave) {
        const edgeOffset = 10; // Distance from the card edge
        const points = [];

        // Generate points for all edges
        // Top edge
        for (let x = 0; x <= canvas.width; x += 1) {
          const y =
            edgeOffset +
            Math.sin(x * wave.frequency + time * wave.speed) * wave.amplitude +
            Math.sin(x * wave.frequency * 0.5 + time * wave.speed * 1.2) *
              wave.amplitude *
              0.5;
          points.push({ x, y });
        }

        // Right edge
        for (let y = 0; y <= canvas.height; y += 1) {
          const x =
            canvas.width -
            edgeOffset +
            Math.sin(y * wave.frequency + time * wave.speed) * wave.amplitude +
            Math.sin(y * wave.frequency * 0.5 + time * wave.speed * 1.2) *
              wave.amplitude *
              0.5;
          points.push({ x, y });
        }

        // Bottom edge (reverse direction)
        for (let x = canvas.width; x >= 0; x -= 1) {
          const y =
            canvas.height -
            edgeOffset +
            Math.sin(x * wave.frequency + time * wave.speed) * wave.amplitude +
            Math.sin(x * wave.frequency * 0.5 + time * wave.speed * 1.2) *
              wave.amplitude *
              0.5;
          points.push({ x, y });
        }

        // Left edge (reverse direction)
        for (let y = canvas.height; y >= 0; y -= 1) {
          const x =
            edgeOffset +
            Math.sin(y * wave.frequency + time * wave.speed) * wave.amplitude +
            Math.sin(y * wave.frequency * 0.5 + time * wave.speed * 1.2) *
              wave.amplitude *
              0.5;
          points.push({ x, y });
        }

        // Draw the wave
        ctx.beginPath();
        ctx.moveTo(points[0].x, points[0].y);

        // Create smooth curve through points
        for (let i = 0; i < points.length - 1; i++) {
          const xc = (points[i].x + points[i + 1].x) / 2;
          const yc = (points[i].y + points[i + 1].y) / 2;
          ctx.quadraticCurveTo(points[i].x, points[i].y, xc, yc);
        }

        // Close the path
        ctx.closePath();

        // Add glow effect
        ctx.shadowColor = wave.color;
        ctx.shadowBlur = 15;

        // Stroke settings
        ctx.strokeStyle = wave.color;
        ctx.lineWidth = wave.width;
        ctx.stroke();
      }

      function drawWaves() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Set global composite operation for better blend
        ctx.globalCompositeOperation = "screen";

        // Draw each wave
        waves.forEach((wave) => {
          drawEdgeWave(wave);
        });

        time += 0.01;
        if (isAnimating) {
          animationFrameId = requestAnimationFrame(drawWaves);
        }
      }

      // Add glass reflection effect
      function addGlassReflection() {
        const gradient = ctx.createLinearGradient(0, 0, canvas.width, 0);
        gradient.addColorStop(0, "rgba(255, 255, 255, 0.1)");
        gradient.addColorStop(0.5, "rgba(255, 255, 255, 0.05)");
        gradient.addColorStop(1, "rgba(255, 255, 255, 0.1)");

        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }

      // Start animation on hover
      card.addEventListener("mouseenter", () => {
        if (!isAnimating) {
          isAnimating = true;
          time = 0;
          drawWaves();
        }
      });

      // Stop animation when mouse leaves
      card.addEventListener("mouseleave", () => {
        isAnimating = false;
        if (animationFrameId) {
          cancelAnimationFrame(animationFrameId);
        }
        ctx.clearRect(0, 0, canvas.width, canvas.height);
      });

      // Handle window resize
      window.addEventListener("resize", () => {
        resizeCanvas();
        if (isAnimating) {
          drawWaves();
        }
      });

      // Optional: Add mouse movement interaction
      card.addEventListener("mousemove", (e) => {
        if (isAnimating) {
          const rect = card.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;

          // Adjust wave amplitudes based on mouse position
          waves.forEach((wave) => {
            const distanceFromCenter = Math.sqrt(
              Math.pow(x - canvas.width / 2, 2) +
                Math.pow(y - canvas.height / 2, 2)
            );
            wave.amplitude = 3 + distanceFromCenter / 100;
