class FeatureEngineer:
    """
    Manages a pipeline of feature engineering with level 1 and level 2 features.
    """
    def __init__(self, lvl1_features=None, lvl2_features=None):
        self.lvl1_features = lvl1_features if lvl1_features else []
        self.lvl2_features = lvl2_features if lvl2_features else []

    def process_features(self, df):
        """
        Processes all features in level 1 and level 2.
        :param df: Input dataframe.
        :return: Processed features dictionary {feature_name: processed_feature}.
        """
        processed_features = {}
        for feature in self.lvl1_features:
            processed_inputs = feature.transform_inputs(df)
            processed_outputs = feature.transform_outputs(processed_inputs)
            processed_features[feature.name] = processed_outputs

        lvl1_outputs = pd.concat(processed_features.values(), axis=1)
        for feature in self.lvl2_features:
            processed_inputs = feature.transform_inputs(lvl1_outputs)
            processed_outputs = feature.transform_outputs(processed_inputs)
            processed_features[feature.name] = processed_outputs

        return processed_features

