def print_sorted_rides(rides, oil_at_home, name, mini):
    results = []

    # Sort single rides
    single_rides = sorted([(r[1], 'Single', r[0]) for r in rides], reverse=True)

    # Generate dual combinations
    dual_rides = []
    for i in range(len(rides)):
        for j in range(i+1, len(rides)):
            total = rides[i][1] + rides[j][1]
            if total <= oil_at_home:
                dual_rides.append((total, 'Dual', rides[i][0], rides[j][0], rides[i][1], rides[j][1]))

    dual_rides.sort(reverse=True)

    all_rides = []

    # Add top 10 single rides
    for amount, ride_type, idx in single_rides[:10]:
        if amount <= oil_at_home:
            all_rides.append((amount, f"{ride_type}: [{idx}] {amount} liters"))

    # Add top 5 dual rides
    for total, ride_type, idx1, idx2, r1, r2 in dual_rides[:5]:
        all_rides.append((total, f"{ride_type}: [{idx1}]{r1} + [{idx2}]{r2} = {total} liters"))

    # Sort combined results
    all_rides.sort(reverse=True)

    for amount, description in all_rides:
        results.append({
            "description": description,
            "amount": amount,
            "meets_minimum": amount >= mini
        })

    return {
        "name": name,
        "available": oil_at_home,
        "rides": results
    }

def get_single_rides(rides, name):
    # Sort single rides by amount
    single_rides = sorted([(r[1], name, r[0]) for r in rides], reverse=True)
    return single_rides

