    results.append(print_sorted_rides(benzinevo_data["diezelevoplus"], float(data['diezelevoplus']), "Diezelevoplus", 11000))
    results.append(print_sorted_rides(benzinevo_data["benzinevo"], float(data['benzin']), "Benzinevo", 11000))
    results.append(print_sorted_rides(benzinevo_data["benzinevoplus"], float(data['benzinevoplus']), "Benzinevoplus", 11000))

