class RobotAction(BaseModel):
    acceleration: float = Field(..., description="Robot acceleration measured in m/s^2")
    steer: float = Field(..., description="Change in robot heading measured in degrees")

    @staticmethod
    def random_action() -> "RobotAction":
        """Generates random actions to be used for testing the simulation engine

        Returns:
            RobotAction: Randomly generated action
        """
        return RobotAction(
            acceleration=random.uniform(
                constants.MAX_ROBOT_ACCELERATION,
                constants.MAX_ROBOT_ACCELERATION
                + constants.ROBOT_ACCELERATION_DISCRETIZATION_MUTIPLIER,
            ),
            steer=random.uniform(
                constants.MAX_STEER,
                constants.MAX_STEER + constants.ROBOT_STEER_DISCRETIZATION_MUTIPLIER,
            ),
        )

    @staticmethod
    def action_space_shape() -> NDArray[np.int64]:
        """
        Returns:
            NDArray[np.int64]: Shape of the action space to be used in gym environment
        """
        return (
            [
                discretize(
                    constants.MAX_ROBOT_ACCELERATION,
                    constants.ROBOT_ACCELERATION_DISCRETIZATION_MUTIPLIER,
                )
                + 1,
                discretize(
                    constants.MAX_STEER, constants.ROBOT_STEER_DISCRETIZATION_MUTIPLIER
                )
                + 1,  # action spaces are exclusive of max, +1 to account for this
            ],
        )

    def undiscretize(self, environment_action: NDArray[np.int64]):
        """Goes from discrete action space to floating point values

        Args:
            environment_action (NDArray[np.int64]): Array of acceleration and steer in discrete integers given by the environment
        """
        self.acceleration = undiscretize(
            environment_action[0], constants.ROBOT_ACCELERATION_DISCRETIZATION_MUTIPLIER
        )
        self.steer = undiscretize(
            environment_action[1], constants.ROBOT_STEER_DISCRETIZATION_MUTIPLIER
        )


# Observations
class Observation(ABC):
    @staticmethod
    @abstractmethod
    def observation_space_shape() -> NDArray[np.int64]:
        pass

    @staticmethod
    @abstractmethod
    def calculate_observation(state: "State", robot_state: RobotState) -> "Observation":
        pass


class StaticObservation(Observation):
    @staticmethod
    def observation_space_shape() -> NDArray[np.int64]:
        return [
            int(constants.MAP_WIDTH) + 1,  # distance to left wall
            int(constants.MAP_WIDTH) + 1,  # distance to right wall
            int(constants.MAP_LENGTH) + 1,  # distance to top wall
            int(constants.MAP_LENGTH) + 1,  # distance to bottom wall
        ] + (
            [
                int(constants.MAP_WIDTH * 2)
                + 1,  # x distance to obstacle (doubled to account for negative x)
                int(constants.MAP_LENGTH * 2)
                + 1,  # y distance to obstacle (doubled to account for negative y)
                int(constants.MAX_OBSTACLE_WIDTH) + 1,  # obstacle width
                int(constants.MAX_OBSTACLE_LENGTH) + 1,  # obstacle length
            ]
            * constants.NUMBER_OF_MAP_OBSTACLES
        )

    @staticmethod
    def calculate_observation(
        state: "State", robot_state: RobotState
    ) -> tuple[NDArray[np.int64], pd.DataFrame]:
        observation: list[float] = []
        discrete_observation: list[int] = []
        robot_heading_rad: float = math.radians(robot_state.heading)

        # Process obstacles
        for obstacle in state.map.obstacles:
            # Relative position of the obstacle with respect to the robot
            dx = obstacle.x - robot_state.x
            dy = obstacle.y - robot_state.y

            # Rotate obstacle into robot's local frame
            x_robot = dx * math.cos(robot_heading_rad) + dy * math.sin(
                robot_heading_rad
            )
            y_robot = -dx * math.sin(robot_heading_rad) + dy * math.cos(
                robot_heading_rad
            )

            # Ensure obstacle positions are bounded within the map dimensions
            x_robot_bounded = max(
                -constants.MAP_WIDTH, min(constants.MAP_WIDTH, x_robot)
            )
            y_robot_bounded = max(
                -constants.MAP_LENGTH, min(constants.MAP_LENGTH, y_robot)
            )

            # Append observation data for the obstacle
            observation.extend(
                [x_robot_bounded, y_robot_bounded, obstacle.width, obstacle.length]
            )

            # Discretize and adjust obstacle coordinates to fit within 0 to MAP_WIDTH*2
            discrete_observation.extend(
                [
                    int(x_robot_bounded + constants.MAP_WIDTH),
                    int(y_robot_bounded + constants.MAP_LENGTH),
                    int(obstacle.width),
                    int(obstacle.length),
                ]
            )

        # Limit the number of obstacles to constants.NUMBER_OF_MAP_OBSTACLES
        observation_features_per_obstacle = 4
        if (
            len(observation)
            > constants.NUMBER_OF_MAP_OBSTACLES * observation_features_per_obstacle
        ):
            observation = observation[
                : constants.NUMBER_OF_MAP_OBSTACLES * observation_features_per_obstacle
            ]

        if (
            len(discrete_observation)
            > constants.NUMBER_OF_MAP_OBSTACLES * observation_features_per_obstacle
        ):
            discrete_observation = discrete_observation[
                : constants.NUMBER_OF_MAP_OBSTACLES * observation_features_per_obstacle
            ]
        else:
            discrete_observation.extend(
                [0]
                * (
                    constants.NUMBER_OF_MAP_OBSTACLES
                    * observation_features_per_obstacle
                    - len(discrete_observation)
                )
            )

        # Calculate wall distances from the robot's point of view
        map_observation = [
            robot_state.x,  # Distance to left wall
            constants.MAP_WIDTH - robot_state.x,  # Distance to right wall
            robot_state.y,  # Distance to bottom wall
            constants.MAP_LENGTH - robot_state.y,  # Distance to top wall
        ]
        discrete_map_observation = [int(x) for x in map_observation]

        # Combine map and obstacle observations into discrete observations
        discrete_observation = discrete_map_observation + discrete_observation

        # Create a DataFrame with labels for each type of observation (walls and obstacles)
        observation_labels = ["wall"] * 4 + [
            "obstacle"
        ] * constants.NUMBER_OF_MAP_OBSTACLES

        # Organize data into a DataFrame-friendly structure
        wall_data = [
            [map_observation[0], 0, constants.MAP_WIDTH, 0],  # Left wall
            [map_observation[1], 0, constants.MAP_WIDTH, 0],  # Right wall
            [0, map_observation[2], 0, constants.MAP_LENGTH],  # Bottom wall
            [0, map_observation[3], 0, constants.MAP_LENGTH],
        ]  # Top wall

        # Split obstacle data into rows for the DataFrame
        obstacle_data = [
            observation[i : i + observation_features_per_obstacle]
            for i in range(0, len(observation), observation_features_per_obstacle)
        ]

        # Combine wall and obstacle data
        df_data = wall_data + obstacle_data
        df = pd.DataFrame(
            df_data,
            columns=["x_robot", "y_robot", "width", "length"],
            index=observation_labels[: len(df_data)],  # Limit labels to match data rows
        )

        obs_shape = StaticObservation.observation_space_shape()
        assert all(
            0 <= obs < bound for obs, bound in zip(discrete_observation, obs_shape)
        ), f"StaticObservation: Observed value {discrete_observation} is out of the bounds {obs_shape}"

        return np.array(discrete_observation), df


class PeopleObservation(Observation):
    # Defines the robot's observation of people
    @staticmethod
    def observation_space_shape() -> NDArray[np.int64]:
        return [
            int(
                constants.MAX_OBSERVABLE_DISTANCE
                / constants.MINIMUM_OBSERVATION_STEP_SIZE
                * 2
            )
            + 1,  # x distance to person (doubled to account for negative x)
