sub GET_stats ($c) {
    my $stats = FileCacher::stats(@{Lists::urls});
    my @sorted_keys = sort {$stats->{$b}{stat} <=> $stats->{$a}{stat}} keys %$stats;
    my %rtoken_stats;
    foreach my $row (@{$c->torrents->rtoken_count()}) {
        $rtoken_stats{$row->{rtoken}} = {
            all_last48h => $row->{last48h},
            all_lifetime => $row->{all_time},
        };
    }
    foreach my $row (@{$c->torrents->interests_rtoken_count()}) {
        $rtoken_stats{$row->{rtoken}}->{interests_last48h} = $row->{last48h};
        $rtoken_stats{$row->{rtoken}}->{interests_lifetime} = $row->{all_time};
    }
    my $content = $c->render_to_string(
        template => 'stats', 
        stats => $stats, 
        sorted_keys => \@sorted_keys,
        largest => $c->torrents->get_largest(),
        most => $c->torrents->get_most(),
        rtoken_stats => \%rtoken_stats,
    );
    $c->render(
        template => 'main',
        content => $content,
    );
};

sub GET_new_new ($c) {
    my $torrents_ref = $c->torrents->new_new();
    my $content = ContentGenerator::simple_list($c, 'row', $torrents_ref);
    $c->render(template => 'main', content => $content);
}

sub GET_interests_lite ($c) {
    my $torrents_ref = $c->torrents->get_interests_lite();
    my $content = ContentGenerator::simple_list($c, 'row', $torrents_ref);
    $c->render(template => 'main', content => $content);
}

sub GET_season_listing ($c) {
    my $torrent_id = $c->param('torrent_id');
    my $torrents_ref = $c->torrents->with_season_sth($torrent_id);

    my $content = '<table>';
    foreach my $torrent (@$torrents_ref) {
        $content .= ContentGenerator::row_str($c, $torrent, 'torrents/season_row');
    }
    $content .= '</table>';

    $c->render(text => $content, format => 'html');
}

sub GET_search_listing ($c) {
    my $search_id = $c->param('search_id');
    my $torrents_ref = $c->torrents->with_column('search_id2', $search_id);

    my $content = '<table>';
    foreach my $torrent (@$torrents_ref) {
        $content .= ContentGenerator::row_str($c, $torrent, 'row');
    }
    $content .= '</table>';

    $c->render(text => $content, format => 'html');
}

sub GET_show_name_listing ($c) {
    my $show_name = $c->param('showname');
    my $alias = $c->dbpatts->one_with_column('pattmatch', $show_name);
    if ($alias) {
        $c->redirect_to('/sn/' . $alias->{pattmain});
    } else {
        my $content = $c->render_to_string(
            template => 'torrents/by_showname',
            episodes => $c->torrents->with_show_name_sth($show_name),
            assigned_show_name => $show_name,
        );
        $c->render(template => 'main', content => $content);
    }
}

sub GET_episodes_listing ($c) {
    my $id = $c->param('torrent_id');
    my $dbtorrents = DBTorrents->new($ENV{DB_PATH});
    my $content = '<table>';
    my $sth = $dbtorrents->get_episodes_from_torrent_id_sth($id);
    my $base_size = 0;
    while (my $torrent = $sth->hash) {
        $base_size = $base_size || $torrent->{size};
        $torrent->{base_size} = $base_size;
        $torrent->{domain_link} = $torrent->{rtoken} ne 'url' ? 
            @{Lists::get_random_index_eq('domains', 0, $torrent->{rtoken})}[1] : undef;
        $content .= $c->render_to_string('torrents/show_name_row', %$torrent);
    }
    $content .= '</table>';
    $c->render(text => $content, format => 'html');
}

