    ***************************************************************/
    if (threadIdx.x < BLOCK_SIZE) {  // peri-row
        // calculate the rows right to the diagonal (upper triangular)
        idx = threadIdx.x;
        for (i = 1; i < BLOCK_SIZE; i++) {
            for (j = 0; j < i; j++)
                peri_row[i][idx] -= dia[i][j] * peri_row[j][idx];
        }
    } else {  // peri-col
        // calculate the columns below the diagonal (lower triangular)
        idx = threadIdx.x - BLOCK_SIZE;
        for (i = 0; i < BLOCK_SIZE; i++) {
            for (j = 0; j < i; j++)
                peri_col[idx][i] -= peri_col[idx][j] * dia[j][i];
            peri_col[idx][i] /= dia[i][i];
        }
    }

    __syncthreads();

    // write back peri_row and peri_col
    if (threadIdx.x < BLOCK_SIZE) {  // peri-row
        idx = threadIdx.x;
        array_offset = (offset + 1) * matrix_dim + offset;
        for (i = 1; i < BLOCK_SIZE; i++) {
            m[array_offset + (blockIdx.x + 1) * BLOCK_SIZE + idx] =
                peri_row[i][idx];
            array_offset += matrix_dim;
        }
    } else {  // peri-col
        idx = threadIdx.x - BLOCK_SIZE;
        array_offset =
            (offset + (blockIdx.x + 1) * BLOCK_SIZE) * matrix_dim + offset;
        for (i = 0; i < BLOCK_SIZE; i++) {
            m[array_offset + idx] = peri_col[i][idx];
            array_offset += matrix_dim;
        }
    }
}

__global__ void lud_internal(float *m, int matrix_dim, int offset) {
    __shared__ float peri_row[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float peri_col[BLOCK_SIZE][BLOCK_SIZE];

    int i;
    float sum;

    int global_row_id = offset + (blockIdx.y + 1) * BLOCK_SIZE;
    int global_col_id = offset + (blockIdx.x + 1) * BLOCK_SIZE;

    peri_row[threadIdx.y][threadIdx.x] =
        m[(offset + threadIdx.y) * matrix_dim + global_col_id + threadIdx.x];
    peri_col[threadIdx.y][threadIdx.x] =
        m[(global_row_id + threadIdx.y) * matrix_dim + offset + threadIdx.x];

    __syncthreads();

    sum = 0;
    for (i = 0; i < BLOCK_SIZE; i++)
        sum += peri_col[threadIdx.y][i] * peri_row[i][threadIdx.x];
    m[(global_row_id + threadIdx.y) * matrix_dim + global_col_id +
      threadIdx.x] -= sum;
}

void lud_cuda(float *m, int matrix_dim) {
    int i = 0;
    dim3 dimBlock(BLOCK_SIZE, BLOCK_SIZE);
    // float *m_debug = (float *)malloc(matrix_dim * matrix_dim *
    // sizeof(float));

    for (i = 0; i < matrix_dim - BLOCK_SIZE; i += BLOCK_SIZE) {
        // process the diagonal m[i : i+BLOCK_SIZE][i : i+BLOCK_SIZE]
        lud_diagonal<<<1, BLOCK_SIZE>>>(m, matrix_dim, i);
        // process m[i+BLOCK_SIZE : matrix_dim][i : i+BLOCK_SIZE] and
        // m[i : i+BLOCK_SIZE][i+BLOCK_SIZE : matrix_dim]
        lud_perimeter<<<(matrix_dim - i) / BLOCK_SIZE - 1, BLOCK_SIZE * 2>>>(
            m, matrix_dim, i);
        // process m[i+BLOCK_SIZE : matrix_dim][i+BLOCK_SIZE : matrix_dim]
        dim3 dimGrid((matrix_dim - i) / BLOCK_SIZE - 1,
                     (matrix_dim - i) / BLOCK_SIZE - 1);
        lud_internal<<<dimGrid, dimBlock>>>(m, matrix_dim, i);
    }
    lud_diagonal<<<1, BLOCK_SIZE>>>(m, matrix_dim, i);
}

// 2d tiling version of lud_diagonal
__global__ void lud_diagonal_v2(float *m, int matrix_dim, int offset) {
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Only one block is launched
    int row = ty;
    int col = tx;

    __shared__ float s_m[BLOCK_SIZE][BLOCK_SIZE];

    s_m[row][col] = m[OFFSET(row + offset, col + offset, matrix_dim)];
    __syncthreads();

    for (int k = 0; k < BLOCK_SIZE; k++) {
        // process the column m[offset : offset + BS][offset + k]
        if (row > k && col == k) {
            s_m[row][col] /= s_m[k][k];
        }
        __syncthreads();

        // process the sub-matrix m[offset : offset + BS][offset : offset + BS]
        if (row > k && col > k) {
            s_m[row][col] -= s_m[row][k] * s_m[k][col];
        }
        __syncthreads();
    }

    m[OFFSET(row + offset, col + offset, matrix_dim)] = s_m[row][col];
}

