    // Call this after all variables are added
    void cacheFields() {
        boost::pfr::for_each_field(T{}, [&](auto&, std::size_t idx) {
            constexpr auto name = boost::pfr::get_name<idx, T>();
            field_ptrs[idx] = &variables.at(std::string(name));
        });
    }

    class Iterator {
    public:
        Iterator(const DataSet& ds, size_t pos) : dataset(ds), position(pos) {}

        bool operator!=(const Iterator& other) const { return position != other.position; }
        Iterator& operator++() { ++position; return *this; }

        struct TimePoint {
            uint64_t timestamp;
            T data;
        };

        TimePoint operator*() const {
            T result;
            boost::pfr::for_each_field(result, [&](auto& field, std::size_t idx) {
                field = (*dataset.field_ptrs[idx])(position);
            });
            return {dataset.time(position), result};
        }

    private:
        const DataSet& dataset;
        size_t position;
    };

    Iterator begin(uint64_t start_time) const {
        auto it = std::lower_bound(time.begin(), time.end(), start_time);
        return Iterator(*this, std::distance(time.begin(), it));
    }

    Iterator end(uint64_t end_time) const {
        auto it = std::upper_bound(time.begin(), time.end(), end_time);
        return Iterator(*this, std::distance(time.begin(), it));
    }

    uint64_t getTime(size_t i) const { return time(i); }

private:
    Eigen::Map<const Array<uint64_t, -1, 1>> time;
    std::unordered_map<std::string, Map<const ArrayXd>> variables;
    FieldArray field_ptrs;
};

